      <div class="spinner"></div>
      <p>読み込み中...</p>
    </div>
    <div v-else-if="showUploadProgressOverlay" class="double-click-overlay upload-overlay">
      <div class="spinner"></div>
      <p>{{ uploadAfterPutPhase ? (isMobile ? 'コミット中...' : 'コミット・ベクトル送信中...') : `アップロード中 ${uploadProgress.current} / ${uploadProgress.total}` }}</p>
    </div>
    <div v-else-if="moveCopyLoading" class="double-click-overlay">
      <div class="spinner"></div>
      <p>{{ moveCopyLoadingMessage }}</p>
    </div>
    <!-- スマホのみ: 一覧・フォルダ・詳細の3タブ（タブレットは PC 同型レイアウトのため出さない） -->
    <div v-if="isMobile" class="cloud-storage-mobile-tabs">
      <button
        type="button"
        class="cloud-mobile-tab"
        :class="{ active: mobilePanel === 'list' }"
        @click="setMobilePanel('list')"
      >
        一覧
      </button>
      <button
        type="button"
        class="cloud-mobile-tab"
        :class="{ active: mobilePanel === 'folder' }"
        @click="setMobilePanel('folder')"
      >
        フォルダ
      </button>
      <button
        type="button"
        class="cloud-mobile-tab"
        :class="{ active: mobilePanel === 'detail' }"
        @click="setMobilePanel('detail')"
      >
        詳細
      </button>
    </div>
    <div
      class="cloud-storage-content"
      :class="{ 'drag-over': isDragOver && !isMobile }"
      @dragover.prevent="isMobile ? () => {} : (isDragOver = dragPayload ? false : true)"
      @dragleave.prevent="isMobile ? () => {} : (isDragOver = false)"
      @drop.prevent="(e) => { if (!isMobile) handleDrop(e) }"
    >
      <!-- 左パネル（全スコープをツリー表示） -->
      <div class="cloud-left-panel" :class="{ 'mobile-panel': isMobile }" v-show="!isMobile || mobilePanel === 'list'">
        <div class="folder-tree-container">
          <div v-if="loading" class="loading-message">読み込み中...</div>
          <div v-else-if="listError" class="error-message">{{ listError }}</div>
          <div v-else class="folder-tree">
            <template v-for="row in treeLines" :key="row.key">
              <div
                v-if="row.type === 'scope'"
                class="tree-item scope-root drop-target"
                :class="{ active: scope === row.scope && currentFolderId === null, 'drop-target-active': !isMobile && dropTargetKey === `scope-${row.scope}` }"
                @click="isMobile ? (handleScopeRowClick(row.scope), row.scope !== 'work' && setMobilePanel('folder')) : handleScopeRowClick(row.scope)"
                @dragover.prevent="(e) => !isMobile && handleDropTargetDragOver(e, `scope-${row.scope}`, null, row.scope)"
                @dragleave="(e) => !isMobile && handleDropTargetDragLeave(e, `scope-${row.scope}`)"
                @drop.prevent="(e) => !isMobile && handleDropTargetDrop(e, null, row.scope)"
              >
                <span
                  v-if="row.hasChildFolders"
                  class="tree-toggle"
                  @click.stop="toggleScope(row.scope)"
                  @touchstart.stop
                >
                  {{ expandedScopes.has(row.scope) ? '▼' : '▶' }}
                </span>
                <span v-else class="tree-toggle tree-toggle-empty"></span>
                <span
                  v-if="row.hasChildFolders"
                  class="tree-icon folder tree-icon-toggle"
                  @click.stop="toggleScope(row.scope)"
                  @touchstart.stop
                >
                  <svg xmlns="http://www.w3.org/2000/svg" width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M22 19a2 2 0 0 1-2 2H4a2 2 0 0 1-2-2V5a2 2 0 0 1 2-2h5l2 3h9a2 2 0 0 1 2 2z"/></svg>
                </span>
                <span v-else class="tree-icon folder">
                  <svg xmlns="http://www.w3.org/2000/svg" width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M22 19a2 2 0 0 1-2 2H4a2 2 0 0 1-2-2V5a2 2 0 0 1 2-2h5l2 3h9a2 2 0 0 1 2 2z"/></svg>
                </span>
                <span class="tree-label">{{ row.label }}</span>
              </div>
              <div
                v-else-if="row.type === 'work-favorite'"
                class="tree-item tree-item-work"
                style="padding-left: 1.5rem"
                @click.stop="toggleWorkFavorite"
              >
                <span v-if="row.hasChildren" class="tree-toggle">{{ expandedWorkFavorite ? '▼' : '▶' }}</span>
                <span v-else class="tree-toggle tree-toggle-empty"></span>
                <span class="tree-label">{{ row.label }}</span>
              </div>
              <div
                v-else-if="row.type === 'work-kind'"
                class="tree-item tree-item-work"
                style="padding-left: 1.5rem"
                @click.stop="toggleWorkKind(row.kind)"
              >
                <span v-if="row.hasChildren" class="tree-toggle">{{ expandedWorkKind.has(row.kind) ? '▼' : '▶' }}</span>
                <span v-else class="tree-toggle tree-toggle-empty"></span>
                <span class="tree-label">{{ row.label }}</span>
              </div>
              <div
                v-else-if="row.type === 'work-year'"
                class="tree-item tree-item-work"
                style="padding-left: 2rem"
                @click.stop="toggleWorkYear(row.kind, row.year)"
              >
                <span v-if="row.hasChildren" class="tree-toggle">{{ expandedWorkYear.has(`${row.kind}-${row.year}`) ? '▼' : '▶' }}</span>
                <span v-else class="tree-toggle tree-toggle-empty"></span>
                <span class="tree-label">{{ row.label }}</span>
              </div>
              <div
                v-else-if="row.type === 'work-mc'"
                class="tree-item tree-item-work"
                style="padding-left: 2.5rem"
                @click.stop="toggleWorkMc(row.kind, row.year, row.mcId)"
              >
                <span v-if="row.hasChildren" class="tree-toggle">{{ expandedWorkMc.has(`${row.kind}-${row.year}-${row.mcId}`) ? '▼' : '▶' }}</span>
                <span v-else class="tree-toggle tree-toggle-empty"></span>
                <span class="tree-label">{{ row.label }}</span>
              </div>
              <div
                v-else-if="row.type === 'work'"
                class="tree-item tree-item-work drop-target"
