                @click="isMobile ? (handleWorkRowClick(row.work), setMobilePanel('folder')) : handleWorkRowClick(row.work)"
                @dragover.prevent="(e) => !isMobile && handleDropTargetDragOverForWork(e, row.work)"
                @dragleave="(e) => !isMobile && handleDropTargetDragLeave(e, `work-${row.work.id}`)"
                @drop.prevent="(e) => !isMobile && handleDropOnWorkRow(e, row.work)"
