                <span class="tree-toggle tree-toggle-empty"></span>
                <span class="tree-label">{{ getWorkDisplayName(row.work) }}</span>
              </div>
              <div
                v-else
                class="tree-item drop-target"
                :class="{ active: scope === row.folder.scope && currentFolderId === row.folder.id, 'drop-target-active': !isMobile && dropTargetKey === `folder-${row.folder.id}` }"
