                @dragleave="(e) => !isMobile && handleDropTargetDragLeave(e, `folder-${row.folder.id}`)"
                @drop.prevent="(e) => !isMobile && handleDropTargetDrop(e, row.folder.id, row.folder.scope)"
              >
                <span
                  v-if="row.hasChildFolders"
                  class="tree-toggle"
                  @click.stop="toggleFolder(row.folder)"
                  @touchstart.stop
                >
                  {{ expandedFolderIds.has(row.folder.id) ? '▼' : '▶' }}
                </span>
                <span v-else class="tree-toggle tree-toggle-empty"></span>
                <span
                  v-if="row.hasChildFolders"
                  class="tree-icon folder tree-icon-toggle"
                  @click.stop="toggleFolder(row.folder)"
                  @touchstart.stop
                >
                  <svg xmlns="http://www.w3.org/2000/svg" width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M22 19a2 2 0 0 1-2 2H4a2 2 0 0 1-2-2V5a2 2 0 0 1 2-2h5l2 3h9a2 2 0 0 1 2 2z"/></svg>
                </span>
                <span v-else class="tree-icon folder">
                  <svg xmlns="http://www.w3.org/2000/svg" width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M22 19a2 2 0 0 1-2 2H4a2 2 0 0 1-2-2V5a2 2 0 0 1 2-2h5l2 3h9a2 2 0 0 1 2 2z"/></svg>
                </span>
                <span class="tree-label">{{ row.folder.name }}</span>
              </div>
            </template>
          </div>
        </div>
      </div>

      <!-- 中央パネル -->
      <div class="cloud-center-panel" :class="{ 'mobile-panel': isMobile, 'tablet-main-panel': isTabletMode }" v-show="isTabletMode ? mobilePanel !== 'detail' : (!isMobile || mobilePanel === 'folder')">
        <div class="center-toolbar" :class="{ 'center-toolbar--mobile-folder': isMobile }">
          <span class="breadcrumb">
            <template v-for="(part, i) in breadcrumbParts" :key="part.folderId ?? 'root'">
              <span
                v-if="i > 0"
                class="breadcrumb-sep"
              > / </span>
              <button
                v-if="scope === 'work' && part?.isScopeRoot"
                type="button"
                class="breadcrumb-part breadcrumb-part-static"
                disabled
              >
                {{ part.label }}
              </button>
              <button
                v-else
                type="button"
                class="breadcrumb-part drop-target"
                :class="{ current: isBreadcrumbPartCurrent(part), 'drop-target-active': !isMobile && dropTargetKey === `breadcrumb-${part.folderId ?? 'root'}` }"
                @click="selectBreadcrumbPart(part)"
                @dragover.prevent="(e) => !isMobile && handleDropTargetDragOver(e, `breadcrumb-${part.folderId ?? 'root'}`, part.folderId, scope)"
                @dragleave="(e) => !isMobile && handleDropTargetDragLeave(e, `breadcrumb-${part.folderId ?? 'root'}`)"
                @drop.prevent="(e) => !isMobile && handleDropTargetDrop(e, part.folderId, scope)"
              >
                {{ part.label }}
              </button>
            </template>
          </span>
          <div
            v-if="uploadLoading || canCloudTouchUpload"
            class="center-toolbar-end"
          >
            <span v-if="uploadLoading" class="upload-status">アップロード中...</span>
            <!-- スマホ・タブレット・PC: アップロードは center-toolbar 右（スマホは一覧タブからフォルダへ切替後に利用） -->
            <div v-if="canCloudTouchUpload" class="mobile-upload-buttons">
              <button
                type="button"
                class="mobile-upload-btn mobile-upload-file"
                title="ファイルをアップロード"
                :disabled="uploadLoading"
                @click="handleCloudTouchUploadClick"
              >
                <PhotoUploadSvgrepoIcon />
              </button>
            </div>
          </div>
          <input
            ref="mobileFileInputRef"
            type="file"
            multiple
            accept="image/*,.heic,.heif,application/pdf,application/zip,.zip,.pdf,.jww"
            class="mobile-file-input-hidden"
            @change="handleMobileFileSelected"
          />
        </div>
        <div class="center-content">
          <div v-if="loading || workItemsLoading" class="loading-message">読み込み中...</div>
          <div v-else-if="listError" class="error-message">{{ listError }}</div>
          <div v-else class="center-file-area">
            <div v-if="scope !== 'work' || selectedWorkId" class="folder-create-row" ref="bulkActionMenuRef">
              <label v-if="!isMobile" class="select-all-checkbox" title="全て選択/解除">
                <input
                  type="checkbox"
                  :checked="isAllChecked"
                  :indeterminate.prop="isIndeterminateChecked"
                  @change="toggleSelectAll"
                />
              </label>
              <button
                type="button"
                class="view-mode-toggle"
                :class="{ active: centerViewMode === 'grid' }"
                :title="centerViewMode === 'grid' ? 'リスト表示' : 'サムネイル表示'"
                @click="centerViewMode = centerViewMode === 'grid' ? 'list' : 'grid'"
              >
                <svg xmlns="http://www.w3.org/2000/svg" width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round">
                  <rect x="3" y="3" width="7" height="7"></rect>
                  <rect x="14" y="3" width="7" height="7"></rect>
                  <rect x="14" y="14" width="7" height="7"></rect>
                  <rect x="3" y="14" width="7" height="7"></rect>
                </svg>
              </button>
              <input
                v-model="newFolderName"
                type="text"
                class="folder-create-input"
                placeholder="新規フォルダ名"
                @focus="isInputFocused = true"
                @blur="isInputFocused = false"
                @keydown.enter="createFolder"
              />
              <button
                class="folder-create-btn"
                title="フォルダ作成"
                :disabled="!newFolderName.trim() || createFolderLoading"
                @click="createFolder"
              >
                {{ createFolderLoading ? '...' : '+' }}
              </button>
              <div v-if="!isMobile" class="bulk-action-wrap">
                <button
                  class="folder-create-btn bulk-action-btn"
                  title="複数選択メニュー"
                  :disabled="checkedIds.size === 0"
                  @click="bulkActionMenuOpen = !bulkActionMenuOpen"
                >
                  ⋯
                </button>
                <div v-if="bulkActionMenuOpen" class="bulk-action-menu">
                  <button :disabled="bulkDownloadLoading" @click="handleBulkDownloadFiles">
                    {{ bulkDownloadLoading ? 'ダウンロード中...' : '選択ファイルをダウンロード' }}
                  </button>
                  <button @click="handleBulkDelete">{{ checkedIds.size > 1 ? '複数削除' : '削除' }}</button>
                </div>
              </div>
            </div>
            <div ref="centerItemsRef" :class="['file-items', centerViewMode === 'grid' ? 'file-grid' : 'file-list']">
            <div
              v-for="item in currentItems"
              :key="item.id"
              :data-nav-id="item.id"
              :class="[centerViewMode === 'grid' ? 'file-grid-item' : 'file-list-item', {
                selected: selectedItem?.id === item.id || checkedIds.has(item.id),
                checked: checkedIds.has(item.id),
                pending: pendingIds.has(item.id),
                'drop-target': item.is_folder && !isMobile,
                'drop-target-active': item.is_folder && dropTargetKey === `center-folder-${item.id}` && !isMobile
              }]"
              :draggable="!isMobile && !pendingIds.has(item.id) && !item._isWork && !isInputFocused"
              @click="handleItemClick(item, $event)"
              @dblclick.prevent="(e) => { if (!props.isMobile) handleRowDoubleClick(item) }"
              @dragstart="(e) => !isMobile && handleItemDragStart(e, item)"
              @dragend="() => !isMobile && handleItemDragEnd()"
              @dragover.prevent="(e) => !isMobile && item.is_folder && handleDropTargetDragOver(e, `center-folder-${item.id}`, item.id, item.scope ?? scope)"
              @dragleave="(e) => !isMobile && item.is_folder && handleDropTargetDragLeave(e, `center-folder-${item.id}`)"
              @drop.prevent="(e) => !isMobile && item.is_folder && handleDropTargetDrop(e, item.id, item.scope ?? scope)"
            >
              <label v-if="!isMobile" class="item-checkbox" @click.stop.prevent="toggleItemChecked(item)" @dblclick.stop.prevent>
                <input type="checkbox" :checked="checkedIds.has(item.id)" tabindex="-1" />
              </label>
              <!-- グリッド表示: 180×135 サムネイル or アイコン -->
              <template v-if="centerViewMode === 'grid'">
                <div class="file-thumbnail-area">
                  <span
                    v-if="item.is_folder && getFolderDescendantFileCount(item) > 0"
                    class="folder-file-count-badge folder-file-count-badge-grid"
                  >{{ getFolderDescendantFileCount(item) }}</span>
                  <img
                    v-if="!item.is_folder && isImageFile(item) && getItemSthumbUrl(item)"
                    class="file-thumbnail-img"
                    :src="getItemSthumbUrl(item)"
                    :alt="item.name"
                    loading="lazy"
                    @error="(e) => { e.target.classList.add('hidden'); e.target.nextElementSibling?.classList?.add('visible') }"
                  />
                  <span
                    class="file-thumbnail-icon"
                    :class="[getIconType(item), {
                      visible: item.is_folder || !isImageFile(item) || !getItemSthumbUrl(item)
                    }]"
                    aria-hidden="true"
                  >
                    <svg v-if="item.is_folder" xmlns="http://www.w3.org/2000/svg" width="48" height="48" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M22 19a2 2 0 0 1-2 2H4a2 2 0 0 1-2-2V5a2 2 0 0 1 2-2h5l2 3h9a2 2 0 0 1 2 2z"/></svg>
                    <svg v-else-if="isPdfFile(item)" xmlns="http://www.w3.org/2000/svg" width="48" height="48" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8z"/><polyline points="14 2 14 8 20 8"/><line x1="16" y1="13" x2="8" y2="13"/><line x1="16" y1="17" x2="8" y2="17"/><polyline points="10 9 9 9 8 9"/></svg>
                    <svg v-else xmlns="http://www.w3.org/2000/svg" width="48" height="48" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8z"/><polyline points="14 2 14 8 20 8"/><line x1="16" y1="13" x2="8" y2="13"/><line x1="16" y1="17" x2="8" y2="17"/></svg>
                  </span>
                </div>
                <div v-if="renameTarget?.id === item.id" class="file-grid-rename" ref="renameInputCenterRef">
                  <input v-model="renameInputValue" type="text" class="file-rename-input" @focus="isInputFocused = true" @blur="isInputFocused = false" @keydown.enter.exact="confirmRename" @keydown.esc="cancelRename" />
                  <button type="button" class="file-rename-btn" title="確定" @click="confirmRename">↲</button>
                </div>
                <span v-else class="file-grid-name" :title="item.name">{{ item.name }}</span>
                <button v-if="!isMobile" class="file-grid-more" title="メニュー" @click.stop="openItemMenu(item, $event)">⋯</button>
              </template>
              <!-- リスト表示 -->
              <template v-else>
                <span
                  v-if="item.is_folder && getFolderDescendantFileCount(item) > 0"
                  class="folder-file-count-badge folder-file-count-badge-list"
                >{{ getFolderDescendantFileCount(item) }}</span>
                <span class="file-icon" :class="getIconType(item)" aria-hidden="true">
                  <svg v-if="item.is_folder" class="file-icon-svg" xmlns="http://www.w3.org/2000/svg" width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M22 19a2 2 0 0 1-2 2H4a2 2 0 0 1-2-2V5a2 2 0 0 1 2-2h5l2 3h9a2 2 0 0 1 2 2z"/></svg>
                  <svg v-else-if="isImageFile(item)" class="file-icon-svg" xmlns="http://www.w3.org/2000/svg" width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><rect x="3" y="3" width="18" height="18" rx="2"/><circle cx="8.5" cy="8.5" r="1.5"/><polyline points="21 15 16 10 5 21"/></svg>
                  <svg v-else-if="isPdfFile(item)" class="file-icon-svg" xmlns="http://www.w3.org/2000/svg" width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8z"/><polyline points="14 2 14 8 20 8"/><line x1="16" y1="13" x2="8" y2="13"/><line x1="16" y1="17" x2="8" y2="17"/><polyline points="10 9 9 9 8 9"/></svg>
                  <svg v-else class="file-icon-svg" xmlns="http://www.w3.org/2000/svg" width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8z"/><polyline points="14 2 14 8 20 8"/><line x1="16" y1="13" x2="8" y2="13"/><line x1="16" y1="17" x2="8" y2="17"/></svg>
                </span>
                <div v-if="renameTarget?.id === item.id" class="file-rename-row" ref="renameInputCenterRef">
                  <input v-model="renameInputValue" type="text" class="file-rename-input" @focus="isInputFocused = true" @blur="isInputFocused = false" @keydown.enter.exact="confirmRename" @keydown.esc="cancelRename" />
                  <button type="button" class="file-rename-btn" title="確定" @click="confirmRename">↲</button>
                </div>
                <span v-else class="file-name">{{ item.name }}</span>
                <div v-if="!isMobile" class="file-actions">
                  <button class="more-btn" title="メニュー" @click.stop="openItemMenu(item, $event)">⋯</button>
                </div>
              </template>
            </div>
            <div v-if="currentItems.length === 0" class="no-data-message">
              <p v-if="scope === 'work' && !selectedWorkId">左のツリーから工事を選択してください</p>
              <p v-else>フォルダが空です</p>
            </div>
            </div>
          </div>
        </div>
      </div>

      <!-- 右パネル（詳細パネル） -->
      <div class="cloud-right-panel" :class="{ 'mobile-panel': isMobile, 'tablet-main-panel': isTabletMode }" v-show="isTabletMode ? mobilePanel === 'detail' : (!isMobile || mobilePanel === 'detail')">
        <div class="cloud-detail-inner">
        <div v-if="!selectedItem" class="no-selection">
          <p>ファイルまたはフォルダを選択してください</p>
        </div>
        <template v-else>
          <div class="detail-actions">
            <button
              v-if="isTabletMode"
              type="button"
              class="detail-back-btn"
              @click="setMobilePanel('folder')"
            >
              ← 戻る
            </button>
            <template v-if="selectedItem.is_folder">
              <button
                v-if="canShowFolderActionButtons"
                class="detail-btn"
                @click="handleDownloadZip"
                :disabled="zipLoading || bulkDownloadLoading || !canUseZipForScope(selectedItem.scope ?? scope)"
              >
                <template v-if="zipLoading || bulkDownloadLoading">
                  <span class="btn-spinner" aria-hidden="true"></span>
                  <span>ZIP</span>
                </template>
                <template v-else>ZIP</template>
              </button>
              <button
                v-if="canShowFolderActionButtons"
                class="detail-btn"
                @click="handleCreateShare"
                :disabled="shareLoading || !canCreateShareForScope(selectedItem.scope ?? scope)"
              >
                {{ shareLoading ? '作成中...' : '共有' }}
              </button>
            </template>
