/** 現在のスコープで使用する items（work のときは workItems） */
const effectiveItems = computed(() =>
  scope.value === 'work' ? workItems.value : items.value
)

const folders = computed(() => effectiveItems.value.filter((i) => i.is_folder === true))
/** 工事以外スコープのフォルダ（左ツリーのhasChildFolders判定用。loadListで更新し、工事選択時に消えないように ref で保持） */
const cachedNonWorkFolders = ref([])

/** id -> item のマップ（path 算出用） */
const idToItem = computed(() => {
  const m = new Map()
  for (const it of effectiveItems.value) m.set(it.id, it)
  return m
})

/** potentialDescendantId が potentialAncestorId の子孫か（自分自身は含む） */
function isDescendantOf(potentialDescendantId, potentialAncestorId) {
  let curr = idToItem.value.get(potentialDescendantId)
  while (curr) {
    if (curr.id === potentialAncestorId) return true
    curr = curr.parent_id ? idToItem.value.get(curr.parent_id) : null
  }
  return false
}

/** フォルダに子孫フォルダがいるか（work以外で再帰削除時の確認用） */
function hasDescendantFolders(folderId) {
  return effectiveItems.value.some((i) => i.is_folder && i.id !== folderId && isDescendantOf(i.id, folderId))
}

/** フォルダ配下のファイル数（読み込み済み items から集計、追加通信なし） */
const folderDescendantFileCounts = computed(() => {
  const counts = new Map()
  const childrenByParent = new Map()
  for (const item of effectiveItems.value) {
    const pid = item.parent_id ?? null
    if (!childrenByParent.has(pid)) childrenByParent.set(pid, [])
    childrenByParent.get(pid).push(item)
  }
  function countFiles(folderId) {
    const cached = counts.get(folderId)
    if (cached != null) return cached
    let total = 0
    for (const child of childrenByParent.get(folderId) ?? []) {
      total += child.is_folder ? countFiles(child.id) : 1
    }
    counts.set(folderId, total)
    return total
  }
  for (const item of effectiveItems.value) {
    if (item.is_folder) countFiles(item.id)
  }
  return counts
})

function getFolderDescendantFileCount(item) {
  if (!item?.is_folder) return 0
  return folderDescendantFileCounts.value.get(item.id) ?? 0
}

/** 各アイテムの path を parent_id から算出 */
function computeItemPath(item) {
  if (!item) return ''
  const parts = []
  let curr = item
  while (curr) {
    parts.unshift(curr.name)
    curr = curr.parent_id ? idToItem.value.get(curr.parent_id) : null
  }
  return parts.join('/')
}

const SCOPE_ROOTS_BASE = [
