function getWorkKindKey(work) {
  if (!work) return 'unknown'
  if (work.kind === 'large') return 'large'
  if (work.kind === 'small') return 'small'
  return 'unknown'
}

const KIND_LABELS = { favorite: 'お気に入り', large: '空家', small: '小口', unknown: 'その他' }

/** 工事スコープでルートを示す breadcrumb の folderId（ドロップ時は null 扱い） */
const WORK_ROOT_FOLDER_IDS = ['work-root', 'work-favorite', 'work-kind', 'work-year', 'work-mc']

/** 案件ツリー用 MC ラベル（master_mc 参照、ホームページビューと同様） */
const mcs = ref([])

/** ユーザーお気に入り（work_id の配列） */
const userWorkFavorites = ref([])

function getYearLabel(year) {
  if (!year) return '-'
  return String(year) === '9999' ? '仮登録' : `${year}年`
}

function getMcLabel(mcId) {
  if (!mcId) return '-'
  const mc = mcs.value.find((m) => m.id == mcId)
  return mc?.label ?? `MC-${mcId}`
}

const WORK_DISPLAY_MAX_LEN = 20
function truncateWorkLabel(s) {
  if (!s || typeof s !== 'string') return ''
  return s.length > WORK_DISPLAY_MAX_LEN ? s.slice(0, WORK_DISPLAY_MAX_LEN) + '…' : s
}
function getWorkDisplayName(work) {
  if (!work) return ''
  const kind = getWorkKindKey(work)
  if (kind === 'large') {
    // 空家: 物件名のみ（display_text を使わない）
    const housingName = work.housing_details?.name || ''
    const building = work.housing_details?.building || ''
    const room = work.room || ''
    const parts = []
    if (housingName) parts.push(housingName)
    if (building) parts.push(building)
    if (room) parts.push(room)
    const objectName = parts.length > 0 ? parts.join('-') : (work.mc_id || work.id)
    return truncateWorkLabel(objectName)
  }
  // 小口: display_text があれば物件名（display_text）、なければ物件名
  const housingName = work.housing_details?.name || ''
  const building = work.housing_details?.building || ''
  const room = work.room || ''
  const parts = []
  if (housingName) parts.push(housingName)
  if (building) parts.push(building)
  if (room) parts.push(room)
  const objectName = parts.length > 0 ? parts.join('-') : (work.mc_id || work.id)
  const displayText = work.display_text ? String(work.display_text).trim() : ''
  if (displayText) return truncateWorkLabel(`${objectName}（${displayText}）`)
  return truncateWorkLabel(objectName)
}

/** works を kind → order_year → mc_id でグループ化（ホームページ検索タブと同様） */
const groupedWorks = computed(() => {
  const kindMap = {}
  works.value.forEach((work) => {
    const kind = getWorkKindKey(work)
    if (!kindMap[kind]) kindMap[kind] = { kind, years: {} }
    const orderYear = work.order_year || 'unknown'
    if (!kindMap[kind].years[orderYear]) {
      kindMap[kind].years[orderYear] = { order_year: orderYear, mcGroups: {} }
    }
    const mcId = String(work.mc_id ?? 'unknown')
    if (!kindMap[kind].years[orderYear].mcGroups[mcId]) {
      kindMap[kind].years[orderYear].mcGroups[mcId] = { mc_id: mcId, works: [] }
    }
    kindMap[kind].years[orderYear].mcGroups[mcId].works.push(work)
  })
  return Object.keys(kindMap)
    .sort((a, b) => {
      const order = { large: 0, small: 1, unknown: 99 }
      return (order[a] ?? 50) - (order[b] ?? 50)
    })
    .map((kind) => ({
      kind,
      years: Object.keys(kindMap[kind].years)
        .sort((a, b) => {
          if (a === 'unknown') return 1
          if (b === 'unknown') return -1
          return Number(b) - Number(a)
        })
        .map((year) => ({
          order_year: year,
          mcGroups: Object.keys(kindMap[kind].years[year].mcGroups)
            .sort((a, b) => {
              if (a === 'unknown') return 1
              if (b === 'unknown') return -1
              return Number(a) - Number(b)
            })
            .map((mcId) => ({
              mc_id: mcId,
              works: kindMap[kind].years[year].mcGroups[mcId].works.sort((a, b) => {
                const nameA = a.housing_details?.name || ''
                const nameB = b.housing_details?.name || ''
                const c = nameA.localeCompare(nameB, 'ja')
                if (c !== 0) return c
                return (a.room || '').localeCompare(b.room || '')
              })
            }))
        }))
    }))
})

/** お気に入りに含まれる案件（work_id でフィルタ） */
const favoriteWorks = computed(() => {
  const favIds = new Set(userWorkFavorites.value.map((f) => f.work_id))
  return works.value
    .filter((w) => favIds.has(w.id))
    .sort((a, b) => {
      const nameA = a.housing_details?.name || ''
      const nameB = b.housing_details?.name || ''
      const c = nameA.localeCompare(nameB, 'ja')
      if (c !== 0) return c
      return (a.room || '').localeCompare(b.room || '')
    })
})

/** スコープ直下に子フォルダがいるか（root = parent_id null）。work は お気に入り or groupedWorks */
function scopeHasChildFolders(scopeKey, foldersForScope) {
  if (scopeKey === 'work') return favoriteWorks.value.length > 0 || groupedWorks.value.length > 0
  return foldersForScope.some((f) => f.scope === scopeKey && f.parent_id == null)
}

/** 指定フォルダ直下に子フォルダがいるか */
function folderHasChildFolders(folder, allFolders) {
  return allFolders.some((f) => f.scope === folder.scope && f.parent_id === folder.id)
}

const treeLines = computed(() => {
  const result = []
  const allFolders = folders.value
  const nonWorkFolders = cachedNonWorkFolders.value
  const scopeExp = expandedScopes.value
  const folderExp = expandedFolderIds.value
  function addFolderChildren(scopeKey, parentId, depth) {
    if (scopeKey === 'work') {
      // 1. お気に入り（ツリー無しで物件名を直接表示）
      const favWorks = favoriteWorks.value
      result.push({ type: 'work-favorite', key: 'work-favorite', label: KIND_LABELS.favorite, hasChildren: favWorks.length > 0 })
      if (expandedWorkFavorite.value && favWorks.length > 0) {
        for (const w of favWorks) {
          result.push({ type: 'work', key: `work-${w.id}`, work: w })
        }
      }
      // 2. 空家・小口・その他（年→MC→物件のツリー）
      const kindsOrder = ['large', 'small', 'unknown']
      for (const kind of kindsOrder) {
        const kindGroup = groupedWorks.value.find((g) => g.kind === kind)
        if (!kindGroup || kindGroup.years.length === 0) continue
        const kindKey = `work-kind-${kindGroup.kind}`
        result.push({ type: 'work-kind', key: kindKey, kind: kindGroup.kind, label: KIND_LABELS[kindGroup.kind] || kindGroup.kind, hasChildren: kindGroup.years.length > 0 })
        if (expandedWorkKind.value.has(kindGroup.kind)) {
          for (const yearGroup of kindGroup.years) {
            const yearKey = `work-year-${kindGroup.kind}-${yearGroup.order_year}`
            result.push({ type: 'work-year', key: yearKey, kind: kindGroup.kind, year: yearGroup.order_year, label: getYearLabel(yearGroup.order_year), hasChildren: yearGroup.mcGroups.length > 0 })
            if (expandedWorkYear.value.has(`${kindGroup.kind}-${yearGroup.order_year}`)) {
              for (const mcGroup of yearGroup.mcGroups) {
                const mcKey = `work-mc-${kindGroup.kind}-${yearGroup.order_year}-${mcGroup.mc_id}`
                result.push({ type: 'work-mc', key: mcKey, kind: kindGroup.kind, year: yearGroup.order_year, mcId: mcGroup.mc_id, label: getMcLabel(mcGroup.mc_id), hasChildren: mcGroup.works.length > 0 })
                if (expandedWorkMc.value.has(`${kindGroup.kind}-${yearGroup.order_year}-${mcGroup.mc_id}`)) {
                  for (const w of mcGroup.works) {
                    result.push({ type: 'work', key: `work-${w.id}`, work: w })
                  }
                }
              }
            }
          }
        }
      }
      return
    }
    const foldersForScope = nonWorkFolders
    foldersForScope
      .filter((f) => {
        if (f.scope !== scopeKey) return false
        return (parentId == null && f.parent_id == null) || f.parent_id === parentId
      })
      .forEach((f) => {
        const hasChildFolders = folderHasChildFolders(f, foldersForScope)
        result.push({ type: 'folder', key: f.id, folder: f, depth, hasChildFolders })
        if (folderExp.has(f.id)) addFolderChildren(scopeKey, f.id, depth + 1)
      })
  }
  for (const { scope: sc, label } of SCOPE_ROOTS.value) {
    const hasChildFolders = scopeHasChildFolders(sc, sc === 'work' ? [] : nonWorkFolders)
    result.push({ type: 'scope', key: `scope-${sc}`, scope: sc, label, hasChildFolders })
    if (scopeExp.has(sc)) addFolderChildren(sc, null, 1)
  }
  return result
})

const currentItems = computed(() => {
  const s = scope.value
  const parentId = currentFolderId.value
  if (s === 'work') {
    if (!selectedWorkId.value) return [] // ルートの案件選択時は中央パネル更新しない
    return effectiveItems.value.filter((item) => {
      return (parentId == null && item.parent_id == null) || item.parent_id === parentId
    })
  }
  return items.value.filter((item) => {
    if (item.scope !== s) return false
    return (parentId == null && item.parent_id == null) || item.parent_id === parentId
  })
})

const canShowFolderActionButtons = computed(() => !!selectedItem.value?.is_folder)
const scopeLabel = computed(() => {
  const o = SCOPE_ROOTS.value.find((r) => r.scope === scope.value)
  return o ? o.label : scope.value
})

/** 選択中の work（案件スコープ時） */
const selectedWork = computed(() =>
  selectedWorkId.value ? works.value.find((w) => w.id === selectedWorkId.value) : null
)

/** フォルダID からルートへのパスセグメントを取得 */
function getPathSegmentsFromFolderId(folderId) {
  if (!folderId) return []
  const segs = []
  let curr = idToItem.value.get(folderId)
  while (curr) {
    segs.unshift({ label: curr.name, folderId: curr.id, isScopeRoot: false })
    curr = curr.parent_id ? idToItem.value.get(curr.parent_id) : null
  }
  return segs
}

const breadcrumbParts = computed(() => {
  const parts = [{ label: scopeLabel.value, folderId: null, isScopeRoot: true }]
  if (scope.value === 'work') {
    if (selectedWork.value) {
      const w = selectedWork.value
      // 工事 / 物件詳細（display_text のみ、20文字で切る）
      parts.push({ label: getWorkDisplayName(w), folderId: 'work-root', isScopeRoot: false })
      const segs = getPathSegmentsFromFolderId(currentFolderId.value)
      parts.push(...segs)
    }
  } else {
    const segs = getPathSegmentsFromFolderId(currentFolderId.value)
    parts.push(...segs)
  }
  return parts
})

async function loadList(opts = {}) {
  loading.value = true
  if (opts.refreshWorkId) workItemsLoading.value = true
  listError.value = ''
  try {
    const body = { action: 'list', scope: '' }
    if (opts.refreshWorkId) body.refresh_work_id = opts.refreshWorkId
    const res = await supabaseService.manageCloudStorage(body)
    const raw = res?.items ?? []
    const shareLinks = res?.share_links ?? {}
    canAccessAllScope.value = res?.can_access_all ?? false
    items.value = raw.map((it) => ({
      id: it.id,
      parent_id: it.parent_id ?? null,
      scope: it.scope ?? 'personal',
      name: it.name != null ? String(it.name) : '',
      is_folder: Boolean(it.is_folder),
      created_at: it.created_at,
      size_bytes: it.size_bytes,
      thumbnail_url: it.thumbnail_url || null,
      sthumb_url: it.sthumb_url || null,
      width: it.width ?? null,
      height: it.height ?? null,
      taken_at: it.taken_at ?? null
    }))
    if (expandedScopes.value.size === 0) {
      // 「全体」は初期状態ではツリーを畳む（マウント時の watch も all を開かない）
      expandedScopes.value = new Set(
        SCOPE_ROOTS.value.map((r) => r.scope).filter((s) => s !== 'all')
      )
    }
    // 全体にアクセスできない場合、初期選択を先頭の表示スコープにフォールバック
    if (!canAccessAllScope.value && scope.value === 'all') {
      const first = SCOPE_ROOTS_VISIBLE[0]
      scope.value = first?.scope ?? 'work'
      currentFolderId.value = null
    }
    if (opts.refreshWorkId && Array.isArray(res?.work_items)) {
      const workRaw = res.work_items
      const workShareLinks = res?.work_share_links ?? {}
      workItems.value = workRaw.map((it) => ({
        id: it.id,
        parent_id: it.parent_id ?? null,
        scope: 'work',
        name: it.name != null ? String(it.name) : '',
        is_folder: Boolean(it.is_folder),
        created_at: it.created_at,
        size_bytes: it.size_bytes,
        thumbnail_url: it.thumbnail_url || null,
        sthumb_url: it.sthumb_url || null,
        public_url: it.public_url || null,
        width: it.width ?? null,
        height: it.height ?? null,
        taken_at: it.taken_at ?? null,
        work_id: opts.refreshWorkId
      }))
      shareUrlForFolder.value = { ...shareUrlForFolder.value, ...workShareLinks }
    }
    shareUrlForFolder.value = { ...shareUrlForFolder.value, ...shareLinks }
  } catch (e) {
    listError.value = e.message || '一覧の取得に失敗しました'
  } finally {
    loading.value = false
    if (opts.refreshWorkId) workItemsLoading.value = false
  }
}

async function loadRefresh(workId) {
  await loadList({ refreshWorkId: workId || undefined })
}

/** 外部（ホーム等）から工事スコープで指定 work をルート直下で開く */
async function openCloudStorageForWork(workId) {
  if (!workId) return
  if (props.isMobile || props.isTabletMode) {
    setMobilePanel('folder')
  }
  await loadWorksFromIndexedDB()
  const work = works.value.find((w) => w.id === workId)
  if (work) {
    handleWorkRowClick(work)
    return
  }
  scope.value = 'work'
  selectedWorkId.value = workId
  currentFolderId.value = null
  if (!expandedScopes.value.has('work')) {
    expandedScopes.value = new Set([...expandedScopes.value, 'work'])
  }
  await loadWorkItems(workId)
  nextTick(() => { selectedItem.value = null })
}

defineExpose({ loadList, openCloudStorageForWork })

const emit = defineEmits(['loading-change', 'blocking-change'])

const isUploadOverlaySuppressed = computed(
  () =>
    uploadOverlayPaused.value ||
    (showOverwriteModal.value && overwriteModalType.value === 'upload')
)

const showUploadProgressOverlay = computed(
  () => uploadProgress.value.total > 0 && !isUploadOverlaySuppressed.value
)

const isUiBlocking = computed(
  () => {
    if (showOverwriteModal.value) return false
    return (
      doubleClickLoading.value ||
      (uploadLoading.value && !isUploadOverlaySuppressed.value) ||
      showUploadProgressOverlay.value ||
      moveCopyLoading.value
    )
  }
)

async function whileUploadOverlayPaused(fn) {
  const shouldPause = uploadProgress.value.total > 0 || uploadLoading.value
  if (shouldPause) uploadOverlayPaused.value = true
  try {
    return await fn()
  } finally {
    if (shouldPause) uploadOverlayPaused.value = false
  }
}

watch([loading, workItemsLoading], () => {
  emit('loading-change', loading.value || workItemsLoading.value)
}, { immediate: true })

watch(
  isUiBlocking,
  (v) => emit('blocking-change', v),
  { immediate: true }
)

watch(items, (val) => {
  cachedNonWorkFolders.value = (val || []).filter((i) => i.is_folder === true)
}, { immediate: true })

function selectScopeFolder(sc, folderId) {
  scope.value = sc
  currentFolderId.value = folderId
  if (!expandedScopes.value.has(sc)) {
    expandedScopes.value = new Set([...expandedScopes.value, sc])
  }
}

function selectFolder(folderId) {
  currentFolderId.value = folderId
}

function isBreadcrumbPartCurrent(part) {
  if (scope.value === 'work' && part?.isScopeRoot) return selectedWorkId.value == null
  if (scope.value === 'work' && WORK_ROOT_FOLDER_IDS.includes(part?.folderId)) return currentFolderId.value == null
  return currentFolderId.value === part?.folderId
}

/** パンくずクリック時（工事スコープの work-root 等を特別扱い） */
function selectBreadcrumbPart(part) {
  if (scope.value === 'work' && part?.isScopeRoot) {
    selectedWorkId.value = null
    currentFolderId.value = null
    workItems.value = []
  } else if (scope.value === 'work' && WORK_ROOT_FOLDER_IDS.includes(part?.folderId)) {
    currentFolderId.value = null
  } else {
    currentFolderId.value = part?.folderId ?? null
  }
}

function handleScopeRowClick(sc) {
  if (sc === 'work') {
    const isActive = scope.value === 'work' && selectedWorkId.value === null && currentFolderId.value === null
    if (isActive) {
      toggleScope(sc)
    } else {
      selectScopeFolder(sc, null)
      selectedWorkId.value = null
      workItems.value = []
    }
  } else {
    const isActive = scope.value === sc && currentFolderId.value === null
    if (isActive) {
      toggleScope(sc)
    } else {
      selectScopeFolder(sc, null)
    }
  }
}

async function loadWorksFromIndexedDB() {
  try {
    const list = await indexedDBService.getAllWorks()
    works.value = (list || []).sort((a, b) => {
      const ay = String(a.order_year ?? '')
      const by = String(b.order_year ?? '')
      if (ay !== by) return by.localeCompare(ay)
      return String(a.mc_id ?? '').localeCompare(String(b.mc_id ?? ''))
    })
  } catch (e) {
    console.error('loadWorksFromIndexedDB:', e)
    works.value = []
  }
}

async function loadWorkItems(workId) {
  if (!workId) {
    workItems.value = []
    return
  }
  workItemsLoading.value = true
  try {
    const res = await supabaseService.manageCloudStorage({ action: 'list', scope: 'work', work_id: workId })
    const raw = res?.items ?? []
    const workShareLinks = res?.share_links ?? {}
    workItems.value = raw.map((it) => ({
      id: it.id,
      parent_id: it.parent_id ?? null,
      scope: 'work',
      name: it.name != null ? String(it.name) : '',
      is_folder: Boolean(it.is_folder),
      created_at: it.created_at,
      size_bytes: it.size_bytes,
      thumbnail_url: it.thumbnail_url || null,
      sthumb_url: it.sthumb_url || null,
      public_url: it.public_url || null,
      width: it.width ?? null,
      height: it.height ?? null,
      taken_at: it.taken_at ?? null,
      work_id: workId
    }))
    shareUrlForFolder.value = { ...shareUrlForFolder.value, ...workShareLinks }
  } catch (e) {
    console.error('loadWorkItems:', e)
    workItems.value = []
  } finally {
    workItemsLoading.value = false
  }
}

function toggleWorkFavorite() {
  expandedWorkFavorite.value = !expandedWorkFavorite.value
}

function toggleWorkKind(kind) {
  const next = new Set(expandedWorkKind.value)
  if (next.has(kind)) next.delete(kind)
  else next.add(kind)
  expandedWorkKind.value = next
}

function toggleWorkYear(kind, year) {
  const key = `${kind}-${year}`
  const next = new Set(expandedWorkYear.value)
  if (next.has(key)) next.delete(key)
  else next.add(key)
  expandedWorkYear.value = next
}

function toggleWorkMc(kind, year, mcId) {
  const key = `${kind}-${year}-${mcId}`
  const next = new Set(expandedWorkMc.value)
  if (next.has(key)) next.delete(key)
  else next.add(key)
  expandedWorkMc.value = next
}

function handleWorkRowClick(work) {
  const isActive = scope.value === 'work' && selectedWorkId.value === work.id
  if (isActive) return
  scope.value = 'work'
  selectedWorkId.value = work.id
  currentFolderId.value = null
  if (!expandedScopes.value.has('work')) {
    expandedScopes.value = new Set([...expandedScopes.value, 'work'])
  }
  loadWorkItems(work.id)
  nextTick(() => { selectedItem.value = null })
}

function handleWorkDoubleClick(item) {
  if (!item?._isWork) return
  const work = works.value.find((w) => w.id === item.id)
  if (work) handleWorkRowClick(work)
}

function handleFolderRowClick(folder) {
  const isActive = scope.value === folder.scope && currentFolderId.value === folder.id
  if (isActive) {
    toggleFolder(folder)
  } else {
    selectScopeFolder(folder.scope, folder.id)
    nextTick(() => { selectedItem.value = folder })
  }
}

const MOVE_DRAG_TYPE = 'application/x-cloud-storage-move'

function handleItemDragStart(e, item) {
  if (pendingIds.value.has(item.id) || item._isWork) {
    e.preventDefault()
    return
  }
  const useMulti = checkedIds.value.has(item.id) && checkedIds.value.size > 1
  const idsToDrag = useMulti ? [...checkedIds.value] : [item.id]
  const itemsToDrag = effectiveItems.value.filter((i) => idsToDrag.includes(i.id) && !i._isWork && !pendingIds.value.has(i.id))
  if (itemsToDrag.length === 0) return
  const payload = {
    items: itemsToDrag.map((i) => ({
      id: i.id,
      is_folder: i.is_folder,
      name: i.name,
      parent_id: i.parent_id ?? null,
      scope: i.scope ?? scope.value,
      work_id: (i.scope ?? scope.value) === 'work' ? (i.work_id ?? selectedWorkId.value) : null
    }))
  }
  dragPayload.value = payload
  e.dataTransfer.setData(MOVE_DRAG_TYPE, JSON.stringify(payload))
  e.dataTransfer.effectAllowed = 'copyMove'
  e.dataTransfer.setData('text/plain', itemsToDrag.length > 1 ? `${itemsToDrag.length}件` : item.name)
}

function handleItemDragEnd() {
  dragPayload.value = null
  dropTargetKey.value = null
}

function canDropOnTarget(payload, targetParentId, targetScope, targetWorkIdForWork = null) {
  if (!payload) return false
  const items = Array.isArray(payload.items) ? payload.items : [{ id: payload.id, is_folder: payload.is_folder, parent_id: payload.parent_id, scope: payload.scope, work_id: payload.work_id }]
  const workId = targetWorkIdForWork ?? selectedWorkId.value
  if (targetScope === 'work' && !workId) return false
  const normTarget = (targetScope === 'work' && (targetParentId == null || WORK_ROOT_FOLDER_IDS.includes(targetParentId))) ? null : targetParentId
  for (const p of items) {
    if (p.scope === targetScope && p.work_id === workId && String(p.parent_id || '') === String(normTarget || '')) return false
    if (p.is_folder && normTarget && (p.id === normTarget || isDescendantOf(normTarget, p.id))) return false
  }
  return true
}

function getDragPayloadItems(payload) {
  return Array.isArray(payload?.items) ? payload.items : (payload ? [payload] : [])
}

function buildSelectedFilesPayloadForTargetFolder(targetFolder) {
  if (!targetFolder?.is_folder) return null
  const selectedFiles = effectiveItems.value
    .filter((i) => checkedIds.value.has(i.id) && !i._isWork && !pendingIds.value.has(i.id) && !i.is_folder && i.id !== targetFolder.id)
  if (selectedFiles.length === 0) return null
  return {
    items: selectedFiles.map((i) => ({
      id: i.id,
      is_folder: i.is_folder,
      name: i.name,
      parent_id: i.parent_id ?? null,
      scope: i.scope ?? scope.value,
      work_id: (i.scope ?? scope.value) === 'work' ? (i.work_id ?? selectedWorkId.value) : null
    }))
  }
}

const canMoveSelectedFilesToContextFolder = computed(() => {
  const targetFolder = contextMenu.value.item
  if (!targetFolder?.is_folder) return false
  const payload = buildSelectedFilesPayloadForTargetFolder(targetFolder)
  if (!payload) return false
  const targetScope = targetFolder.scope ?? scope.value
  return canDropOnTarget(payload, targetFolder.id, targetScope)
})

function handleDropTargetDragOver(e, targetKey, targetParentId, targetScope, targetWorkIdForWork = null) {
  if (!dragPayload.value) return
  if (canDropOnTarget(dragPayload.value, targetParentId, targetScope, targetWorkIdForWork)) {
    e.preventDefault()
    e.dataTransfer.dropEffect = 'move'
    dropTargetKey.value = targetKey
  } else {
    e.dataTransfer.dropEffect = 'none'
    dropTargetKey.value = null
  }
}

function handleDropTargetDragOverForWork(e, work) {
  if (!dragPayload.value) return
  if (canDropOnTarget(dragPayload.value, null, 'work', work.id)) {
    e.preventDefault()
    e.dataTransfer.dropEffect = 'copy'
    dropTargetKey.value = `work-${work.id}`
  } else {
    e.dataTransfer.dropEffect = 'none'
    dropTargetKey.value = null
  }
}

async function handleDropOnWorkRow(e, work) {
  dropTargetKey.value = null
  const raw = e.dataTransfer?.getData(MOVE_DRAG_TYPE)
  if (!raw) return
  let payload
  try {
    payload = JSON.parse(raw)
  } catch {
    return
  }
  if (!canDropOnTarget(payload, null, 'work', work.id)) return
  e.preventDefault()
  selectedWorkId.value = work.id
  scope.value = 'work'
  await handleDropTargetDrop(e, null, 'work')
}

function handleDropTargetDragLeave(e, targetKey) {
  if (e.currentTarget?.contains(e.relatedTarget)) return
  if (dropTargetKey.value === targetKey) dropTargetKey.value = null
}

const SAME_NAME_ERROR_STR = '同名のファイルが既に存在'
function isSameNameOnlyErrors(errors) {
  if (!Array.isArray(errors) || errors.length === 0) return false
  return errors.every((e) => (e?.error || '').includes(SAME_NAME_ERROR_STR))
}

async function handleDropTargetDrop(e, targetParentId, targetScope) {
  dropTargetKey.value = null
  const raw = e.dataTransfer?.getData(MOVE_DRAG_TYPE)
  if (!raw) return
  let payload
  try {
    payload = JSON.parse(raw)
  } catch {
    return
  }
  const itemsToProcess = getDragPayloadItems(payload)
  if (itemsToProcess.length === 0) return
  if (!canDropOnTarget(payload, targetParentId, targetScope)) return
  e.preventDefault()
  await executeMoveCopyFromPayload(payload, targetParentId, targetScope)
}

async function executeMoveCopyFromPayload(payload, targetParentId, targetScope) {
  const itemsToProcess = getDragPayloadItems(payload)
  if (itemsToProcess.length === 0) return
  if (!canDropOnTarget(payload, targetParentId, targetScope)) return
  const targetWorkId = targetScope === 'work' ? (selectedWorkId.value ?? null) : null
  const effectiveTargetParentId = (targetScope === 'work' && targetParentId && WORK_ROOT_FOLDER_IDS.includes(targetParentId)) ? null : targetParentId
  const copyItems = itemsToProcess.filter((p) => p.scope !== targetScope || (p.scope === 'work' && targetScope === 'work' && p.work_id !== targetWorkId))
  const moveItems = itemsToProcess.filter((p) => !copyItems.includes(p))
  const hasCopy = copyItems.length > 0
  const hasMove = moveItems.length > 0
  const idsToPending = itemsToProcess.map((p) => p.id)
  const ctx = { copyItems, moveItems, targetScope, targetWorkId, effectiveTargetParentId, idsToPending }

  const fileItemsToCheck = [...copyItems.filter((p) => !p.is_folder), ...moveItems.filter((p) => !p.is_folder)]
  const fileNamesToCheck = fileItemsToCheck.map((p) => p.name)

  if (fileNamesToCheck.length > 0) {
    const existing = getExistingFilesInTargetFolder(targetScope, targetWorkId, effectiveTargetParentId)
    if (existing) {
      const existingNames = new Set(existing.map((e) => e.name))
      const conflictNames = fileNamesToCheck.filter((n) => existingNames.has(n))
      if (conflictNames.length > 0) {
        const conflictTargetIds = [...new Set(existing.filter((e) => conflictNames.includes(e.name)).map((e) => e.id))]
        moveCopyOverwriteConflictNames.value = [...new Set(conflictNames)]
        moveCopyOverwriteContext.value = { ...ctx, conflictTargetIds }
        overwriteModalType.value = 'move_copy'
        showOverwriteModal.value = true
        return
      }
    }
  }

  if (hasCopy || hasMove) {
    moveCopyLoadingMessage.value = hasCopy && hasMove ? '確認中...' : hasCopy ? 'コピー確認中...' : '移動確認中...'
    moveCopyLoading.value = true
    pendingIds.value = new Set([...pendingIds.value, ...idsToPending])
  }
  const allErrors = []
  let conflictTargetIds = []
  if (copyItems.length > 0) {
    const copyCheckRes = await supabaseService.manageCloudStorage({
      action: 'check_copy_batch',
      target_scope: targetScope,
      target_parent_id: effectiveTargetParentId || null,
      target_work_id: targetScope === 'work' ? targetWorkId : null,
      items: copyItems.map((p) => ({ id: p.id, name: p.name, is_folder: p.is_folder, scope: p.scope, work_id: p.scope === 'work' ? p.work_id : undefined }))
    }).catch((err) => ({ all_ok: false, errors: [{ error: err.message }] }))
    if (!copyCheckRes?.all_ok && copyCheckRes?.errors?.length > 0) {
      allErrors.push(...copyCheckRes.errors)
      conflictTargetIds.push(...copyCheckRes.errors.map((e) => e.conflict_target_id).filter(Boolean))
    }
  }
  if (moveItems.length > 0) {
    const moveCheckRes = await supabaseService.manageCloudStorage({
      action: 'check_move_batch',
      target_scope: targetScope,
      target_parent_id: effectiveTargetParentId || null,
      target_work_id: targetScope === 'work' ? targetWorkId : null,
      items: moveItems.map((p) => ({ id: p.id, name: p.name, is_folder: p.is_folder, scope: p.scope, work_id: p.scope === 'work' ? p.work_id : undefined }))
    }).catch((err) => ({ all_ok: false, errors: [{ error: err.message }] }))
    if (!moveCheckRes?.all_ok && moveCheckRes?.errors?.length > 0) {
      allErrors.push(...moveCheckRes.errors)
      conflictTargetIds.push(...moveCheckRes.errors.map((e) => e.conflict_target_id).filter(Boolean))
    }
  }
  if (allErrors.length > 0) {
    if (isSameNameOnlyErrors(allErrors)) {
      conflictTargetIds = [...new Set(conflictTargetIds)]
      moveCopyOverwriteConflictNames.value = [...new Set(allErrors.map((e) => e.name || e.id).filter(Boolean))]
      moveCopyOverwriteContext.value = { ...ctx, conflictTargetIds }
      overwriteModalType.value = 'move_copy'
      showOverwriteModal.value = true
    } else {
      await dialog.alert(allErrors.map((x) => `${x.name || x.id || ''}: ${x.error}`).join('\n'), { title: 'エラー' })
    }
    if (hasCopy || hasMove) {
      moveCopyLoading.value = false
      pendingIds.value = new Set([...pendingIds.value].filter((id) => !idsToPending.includes(id)))
    }
    return
  }
  await doMoveCopy(ctx)
}

async function handleMenuMoveSelectedFiles() {
