function cancelMoveCopyOverwrite() {
  showOverwriteModal.value = false
  overwriteModalType.value = 'upload'
  moveCopyOverwriteConflictNames.value = []
  moveCopyOverwriteContext.value = null
}

async function confirmMoveCopyOverwrite() {
  const ctx = moveCopyOverwriteContext.value
  showOverwriteModal.value = false
  moveCopyOverwriteConflictNames.value = []
  moveCopyOverwriteContext.value = null
  if (!ctx || !ctx.conflictTargetIds?.length) return
  const { targetScope, targetWorkId } = ctx
  moveCopyLoadingMessage.value = '上書きのため既存ファイルを削除中...'
  moveCopyLoading.value = true
  try {
    const body = {
      action: 'delete_batch',
      scope: targetScope,
      work_id: targetScope === 'work' ? targetWorkId : undefined,
      items: ctx.conflictTargetIds.map((id) => ({ id, is_folder: false }))
    }
