    await doMoveCopy(ctx)
  } catch (err) {
    await dialog.alert(err.message || '削除に失敗しました', { title: 'エラー' })
  }
}

async function doMoveCopy(ctx) {
  const { copyItems, moveItems, targetScope, targetWorkId, effectiveTargetParentId, idsToPending } = ctx
  const hasCopy = copyItems.length > 0
  const hasMove = moveItems.length > 0
  moveCopyLoadingMessage.value = hasCopy ? 'コピー中...' : '移動中...'
  moveCopyLoading.value = true
  pendingIds.value = new Set([...pendingIds.value, ...idsToPending])
  try {
    if (moveItems.length > 0) {
      await supabaseService.manageCloudStorage({
        action: 'move_batch',
        target_scope: targetScope,
        target_parent_id: effectiveTargetParentId || null,
        target_work_id: targetScope === 'work' ? targetWorkId : null,
        items: moveItems.map((p) => ({ id: p.id, is_folder: p.is_folder, scope: p.scope, work_id: p.scope === 'work' ? p.work_id : undefined }))
      })
    }
    const copiedIds = []
    if (copyItems.length > 0) {
      const copyFolders = copyItems.filter((p) => p.is_folder)
      const copyFiles = copyItems.filter((p) => !p.is_folder)
      let idMap = {} // 旧親ID -> 新親ID（copy_folder_structure の id_map）
      const allNewFolderIds = []
      let structRes = null
      if (copyFolders.length > 0) {
        moveCopyLoadingMessage.value = 'フォルダ構造を登録中...'
        const scope0 = copyFolders[0].scope
        const workId0 = scope0 === 'work' ? (copyFolders[0].work_id ?? null) : null
        structRes = await supabaseService.manageCloudStorage({
          action: 'copy_folder_structure',
          scope: scope0,
          target_scope: targetScope,
          work_id: scope0 === 'work' ? workId0 : undefined,
          target_work_id: targetScope === 'work' ? targetWorkId : undefined,
          target_parent_id: effectiveTargetParentId || null,
          folder_ids: copyFolders.map((p) => p.id)
        })
        idMap = structRes?.id_map ?? {}
        allNewFolderIds.push(...(structRes?.folder_ids ?? []))
      }
      const filesToCopy = [...copyFiles]
      if (copyFolders.length > 0) {
        const filesInFolders = Array.isArray(structRes?.files_in_folders) ? structRes.files_in_folders : []
        for (const f of filesInFolders) {
          filesToCopy.push({ id: f.id, parent_id: f.parent_id ?? null, scope: copyFolders[0].scope, work_id: copyFolders[0].work_id ?? null })
        }
      }
      if (filesToCopy.length > 0) {
        moveCopyLoadingMessage.value = 'ファイルをコピー中...'
        for (let i = 0; i < filesToCopy.length; i += UPLOAD_CONCURRENCY) {
          const chunk = filesToCopy.slice(i, i + UPLOAD_CONCURRENCY)
          const chunkResults = await Promise.all(
            chunk.map((p) => {
              const tgtParent = (p.parent_id && idMap[p.parent_id]) ? idMap[p.parent_id] : (effectiveTargetParentId || null)
              const body = { action: 'copy', scope: p.scope ?? copyFolders[0]?.scope, target_scope: targetScope, id: p.id, target_parent_id: tgtParent }
              if ((p.scope ?? copyFolders[0]?.scope) === 'work' && (p.work_id ?? copyFolders[0]?.work_id)) body.work_id = p.work_id ?? copyFolders[0]?.work_id
              if (targetScope === 'work' && targetWorkId) body.target_work_id = targetWorkId
              return supabaseService.manageCloudStorage(body)
            })
          )
          for (const res of chunkResults) {
            if (res?.id) copiedIds.push(res.id)
          }
        }
      }
      copiedIds.push(...allNewFolderIds)
      if (copiedIds.length > 0) {
        const commitBody = { action: 'commit', scope: targetScope, ids: copiedIds }
        if (targetScope === 'work' && targetWorkId) commitBody.work_id = targetWorkId
        await supabaseService.manageCloudStorage(commitBody)
      }
    }
    if (targetScope === 'work' && targetWorkId) {
      await loadRefresh(targetWorkId)
    } else {
      await loadList()
    }
    selectScopeFolder(targetScope, effectiveTargetParentId)
  } catch (err) {
    await dialog.alert(err.message || '処理に失敗しました', { title: 'エラー' })
  } finally {
    pendingIds.value = new Set([...pendingIds.value].filter((id) => !idsToPending.includes(id)))
    moveCopyLoading.value = false
  }
}

function toggleScope(sc) {
  const next = new Set(expandedScopes.value)
  if (next.has(sc)) next.delete(sc)
  else next.add(sc)
  expandedScopes.value = next
}

function toggleFolder(folder) {
  const next = new Set(expandedFolderIds.value)
  if (next.has(folder.id)) next.delete(folder.id)
  else next.add(folder.id)
  expandedFolderIds.value = next
}

const isAllChecked = computed(() => {
  const items = currentItems.value.filter((i) => !i._isWork && !pendingIds.value.has(i.id))
  if (items.length === 0) return false
  return items.every((i) => checkedIds.value.has(i.id))
})
const isIndeterminateChecked = computed(() => {
  const items = currentItems.value.filter((i) => !i._isWork && !pendingIds.value.has(i.id))
  if (items.length === 0) return false
  const n = items.filter((i) => checkedIds.value.has(i.id)).length
  return n > 0 && n < items.length
})

function toggleSelectAll() {
  const items = currentItems.value.filter((i) => !i._isWork && !pendingIds.value.has(i.id))
  if (items.length === 0) return
  const allChecked = items.every((i) => checkedIds.value.has(i.id))
  const next = new Set(checkedIds.value)
  if (allChecked) {
    items.forEach((i) => next.delete(i.id))
  } else {
    items.forEach((i) => next.add(i.id))
  }
  checkedIds.value = next
}

function clearAllChecked() {
  checkedIds.value = new Set()
  bulkActionMenuOpen.value = false
  selectionAnchorId.value = null
}

function toggleItemChecked(item) {
  if (item._isWork || pendingIds.value.has(item.id)) return
  const next = new Set(checkedIds.value)
  const wasChecked = next.has(item.id)
  if (wasChecked) next.delete(item.id)
  else next.add(item.id)
  checkedIds.value = next
  if (wasChecked) {
    if (selectedItem.value?.id === item.id) {
      selectedItem.value = null
      previewUrl.value = ''
      previewUrlItemId.value = null
    }
    if (selectionAnchorId.value === item.id) selectionAnchorId.value = null
  } else {
    selectedItem.value = item
    selectionAnchorId.value = item.id
    updatePreviewForSelectedItem(item)
  }
}

function handleItemClick(item, ev) {
  if (!props.isMobile && !isInputFocused.value && ev?.shiftKey) {
    applyRangeSelectionToItem(item)
    return
  }
  const isCtrlLikePressed = !!(ev?.ctrlKey || ev?.metaKey)
  if (!props.isMobile && !isInputFocused.value && isCtrlLikePressed) {
    toggleItemChecked(item)
    return
  }
  if (props.isMobile || props.isTabletMode) {
    if (item.is_folder) handleDoubleClick(item)
    else {
      selectItem(item)
      setMobilePanel('detail')
    }
    return
  }
  selectItem(item)
}

function getNavigableItems() {
  return currentItems.value.filter((i) => !i._isWork && !pendingIds.value.has(i.id))
}

function updatePreviewForSelectedItem(item) {
  if (!item || item.is_folder || !isImageFile(item)) {
    previewUrl.value = ''
    previewUrlItemId.value = null
    return
  }
  const itemId = item.id
  const immediate = item.sthumb_url || item.thumbnail_url || ''
  if (immediate) {
    previewUrl.value = immediate
    previewUrlItemId.value = itemId
  }
  // 同期 URL が無い場合は previewUrl をクリアせず、読込完了まで前の画像を表示し続ける

  const requestItemId = itemId
  fetchThumbnailUrl(item).then((url) => {
    if (selectedItem.value?.id !== requestItemId) return
    const resolved = url || item.sthumb_url || item.thumbnail_url || ''
    if (resolved) {
      previewUrl.value = resolved
      previewUrlItemId.value = requestItemId
      return
    }
    fetchSignedUrl(item).then((u) => {
      if (selectedItem.value?.id !== requestItemId) return
      if (u) {
        previewUrl.value = u
        previewUrlItemId.value = requestItemId
      }
    })
  })
}

function selectSingleItem(item) {
  if (!item) return
  selectedItem.value = item
  checkedIds.value = new Set([item.id])
  selectionAnchorId.value = item.id
  updatePreviewForSelectedItem(item)
  scrollCenterItemIntoView(item.id)
}

function applyRangeSelectionByIndices(anchorIndex, targetIndex, list) {
  if (!list.length) return
  const start = Math.min(anchorIndex, targetIndex)
  const end = Math.max(anchorIndex, targetIndex)
  checkedIds.value = new Set(list.slice(start, end + 1).map((i) => i.id))
  const targetItem = list[targetIndex]
  selectedItem.value = targetItem
  updatePreviewForSelectedItem(targetItem)
  scrollCenterItemIntoView(targetItem?.id)
}

function scrollCenterItemIntoView(itemId) {
  const id = itemId != null ? String(itemId) : ''
  if (!id) return
  nextTick(() => {
    const root = centerItemsRef.value
    if (!root || typeof root.querySelector !== 'function') return
    const selectorId =
      typeof CSS !== 'undefined' && CSS.escape
        ? CSS.escape(id)
        : id.replace(/"/g, '\\"')
    const el = root.querySelector(`[data-nav-id="${selectorId}"]`)
    if (!el || typeof el.scrollIntoView !== 'function') return
    el.scrollIntoView({ block: 'nearest', inline: 'nearest' })
  })
}

function applyRangeSelectionToItem(item) {
  const list = getNavigableItems()
  if (list.length === 0) return
  const targetIndex = list.findIndex((i) => i.id === item.id)
  if (targetIndex === -1) return
  const anchorId = selectionAnchorId.value ?? selectedItem.value?.id ?? list[0].id
  const anchorIndex = Math.max(0, list.findIndex((i) => i.id === anchorId))
  selectionAnchorId.value = list[anchorIndex]?.id ?? item.id
  applyRangeSelectionByIndices(anchorIndex, targetIndex, list)
}

function getGridColumnCount() {
  if (centerViewMode.value !== 'grid') return 1
  const root = centerItemsRef.value
  if (!root) return 1
  const nodes = [...root.querySelectorAll('.file-grid-item')]
  if (nodes.length <= 1) return 1
  const firstTop = nodes[0].offsetTop
  let cols = 0
  for (const n of nodes) {
    if (Math.abs(n.offsetTop - firstTop) <= 2) cols++
    else break
  }
  return Math.max(1, cols || 1)
}

function resolveNextIndexByArrow(currentIndex, key, step) {
  if (key === 'ArrowLeft' || key === 'ArrowUp') return Math.max(0, currentIndex - step)
  return currentIndex + step
}

function handleListKeydown(ev) {
  if (!props.isActive || props.isMobile || isInputFocused.value) return
  const key = ev?.key
  if (!['ArrowLeft', 'ArrowRight', 'ArrowUp', 'ArrowDown'].includes(key)) return
  const target = ev.target
  const tag = target?.tagName?.toLowerCase?.()
  const editing = tag === 'input' || tag === 'textarea' || target?.isContentEditable
  if (editing) return

  const list = getNavigableItems()
  if (list.length === 0) return
  ev.preventDefault()

  const selectedId = selectedItem.value?.id
  let currentIndex = list.findIndex((i) => i.id === selectedId)
  if (currentIndex < 0) currentIndex = 0
  const step = centerViewMode.value === 'grid'
    ? (key === 'ArrowUp' || key === 'ArrowDown' ? getGridColumnCount() : 1)
    : 1
  const nextIndex = Math.max(0, Math.min(list.length - 1, resolveNextIndexByArrow(currentIndex, key, step)))
  if (nextIndex === currentIndex && selectedId) return

  if (ev.shiftKey) {
    const anchorId = selectionAnchorId.value ?? selectedId ?? list[0].id
    const anchorIndexRaw = list.findIndex((i) => i.id === anchorId)
    const anchorIndex = anchorIndexRaw >= 0 ? anchorIndexRaw : currentIndex
    if (!selectionAnchorId.value) selectionAnchorId.value = list[anchorIndex]?.id ?? list[0].id
    applyRangeSelectionByIndices(anchorIndex, nextIndex, list)
  } else {
    selectSingleItem(list[nextIndex])
  }
}

function selectItem(item) {
  if (pendingIds.value.has(item.id)) return
  if (item._isWork) {
    selectedItem.value = item
    selectionAnchorId.value = null
    previewUrl.value = ''
    previewUrlItemId.value = null
    return
  }
  selectSingleItem(item)
}

function getIconType(item) {
  if (item.is_folder) return 'folder'
  if (isImageFile(item)) return 'image'
  if (isPdfFile(item)) return 'pdf'
  return 'file'
}

/** グリッド表示用のSサムネイルURL（sthumb優先、なければthumbnail） */
function getItemSthumbUrl(item) {
  return item?.sthumb_url || item?.thumbnail_url || ''
}

function isImageFile(item) {
  const ext = (item.name || '').split('.').pop()?.toLowerCase()
  return ['jpg', 'jpeg', 'png', 'gif', 'webp', 'bmp'].includes(ext || '')
}

function isPdfFile(item) {
  return (item.name || '').toLowerCase().endsWith('.pdf')
}

function isDetailPreviewModalOpenable(item) {
  return isImageFile(item) || isPdfFile(item)
}

async function handleBulkDelete() {
  const ids = [...checkedIds.value]
  if (ids.length === 0) return
  const items = effectiveItems.value.filter((i) => ids.includes(i.id))
  if (items.length === 0) return
  bulkActionMenuOpen.value = false
  const sc = scope.value
  const isWork = sc === 'work'
  const workId = isWork ? (selectedWorkId.value ?? items[0]?.work_id) : null
  const checkBody = {
    action: 'check_delete_batch',
    scope: sc,
    items: items.map((i) => ({ id: i.id, name: i.name, is_folder: i.is_folder }))
  }
  if (isWork) checkBody.work_id = workId
  moveCopyLoadingMessage.value = '削除確認中...'
  moveCopyLoading.value = true
  pendingIds.value = new Set([...pendingIds.value, ...ids])
  try {
    const res = await supabaseService.manageCloudStorage(checkBody)
    if (!res?.all_ok && res?.errors?.length > 0) {
      const msg = res.errors.map((e) => `${e.name || e.id}: ${e.error}`).join('\n')
      await dialog.alert(`削除できません:\n${msg}`, { title: 'エラー' })
      moveCopyLoading.value = false
      pendingIds.value = new Set([...pendingIds.value].filter((id) => !ids.includes(id)))
      return
    }
    const subfolders = res?.items_with_subfolders ?? []
    if (subfolders.length > 0) {
      const names = subfolders.map((f) => f.name || f.id).join('\n')
      const ok = await dialog.confirm(`以下のフォルダにはサブフォルダが含まれています。\n全て削除しますか？\n\n${names}`, { title: '確認' })
      if (!ok) {
        moveCopyLoading.value = false
        pendingIds.value = new Set([...pendingIds.value].filter((id) => !ids.includes(id)))
        return
      }
    } else {
      const ok = await dialog.confirm(`${items.length}件を削除しますか？`, { title: '確認' })
      if (!ok) {
        moveCopyLoading.value = false
        pendingIds.value = new Set([...pendingIds.value].filter((id) => !ids.includes(id)))
        return
      }
    }
  } catch (e) {
    await dialog.alert(e.message || '削除チェックに失敗しました', { title: 'エラー' })
    moveCopyLoading.value = false
    pendingIds.value = new Set([...pendingIds.value].filter((id) => !ids.includes(id)))
    return
  }
  moveCopyLoadingMessage.value = '削除中...'
  try {
    const body = { action: 'delete_batch', scope: sc, items: items.map((i) => ({ id: i.id, name: i.name, is_folder: i.is_folder })) }
    if (isWork) body.work_id = workId
    await supabaseService.manageCloudStorage(body)
  } catch (e) {
    await dialog.alert(e.message || '削除に失敗しました', { title: 'エラー' })
  } finally {
    moveCopyLoading.value = false
    pendingIds.value = new Set([...pendingIds.value].filter((id) => !ids.includes(id)))
    checkedIds.value = new Set([...checkedIds.value].filter((id) => !ids.includes(id)))
    selectedItem.value = null
    if (isWork && workId) {
      await loadRefresh(workId)
    } else {
      await loadList()
    }
  }
}

async function handleBulkDownloadFiles() {
  const ids = [...checkedIds.value]
  if (ids.length === 0) return
  const selectedItems = effectiveItems.value.filter((i) => ids.includes(i.id))
  bulkActionMenuOpen.value = false
  if (selectedItems.length === 0) {
    await dialog.alert('選択中にダウンロード可能な項目がありません', { title: 'エラー' })
    return
  }
  bulkDownloadLoading.value = true
  try {
    for (const item of selectedItems) {
      try {
        if (item.is_folder) {
          await downloadFolderAsZip(item)
        } else {
          await downloadSingleFile(item)
        }
      } catch {}
    }
  } finally {
    bulkDownloadLoading.value = false
  }
}

function openItemMenu(item, ev) {
  if (pendingIds.value.has(item.id)) return
  const rect = ev.target.getBoundingClientRect()
  contextMenu.value = {
    item,
    right: window.innerWidth - rect.right,
    top: rect.bottom + 4
  }
}

function closeContextMenu() {
  contextMenu.value = { item: null, x: 0, y: 0 }
}

function startRename(item, fromPanel = 'center') {
  if (pendingIds.value.has(item.id)) return
  renameTarget.value = item
  renameFromPanel.value = fromPanel
  renameInputValue.value = item.name
  nextTick(() => {
    const raw = fromPanel === 'detail' ? renameInputDetailRef.value : renameInputCenterRef.value
    const el = Array.isArray(raw) ? raw[0] : raw
    const input = el?.querySelector?.('input') ?? el
    if (input?.focus) input.focus()
  })
  if (renameClickOutsideHandler) {
    document.removeEventListener('mousedown', renameClickOutsideHandler)
  }
  renameClickOutsideHandler = (e) => {
    const row = e.target?.closest?.('.file-rename-row, .detail-rename-row')
    if (!row) confirmRename()
  }
  setTimeout(() => document.addEventListener('mousedown', renameClickOutsideHandler), 0)
}

function removeRenameClickOutsideListener() {
  if (renameClickOutsideHandler) {
    document.removeEventListener('mousedown', renameClickOutsideHandler)
    renameClickOutsideHandler = null
  }
}

function cancelRename() {
  renameTarget.value = null
  renameInputValue.value = ''
  removeRenameClickOutsideListener()
}

async function confirmRename() {
  const item = renameTarget.value
  if (!item) return
  const newName = renameInputValue.value.trim()
  if (!newName || newName === item.name) {
    cancelRename()
    return
  }
  const id = item.id
  const prevName = item.name
  const isWork = (item.scope ?? scope.value) === 'work'
  pendingIds.value = new Set([...pendingIds.value, id])
  if (isWork) {
    const idx = workItems.value.findIndex((i) => i.id === id)
    if (idx !== -1) {
      workItems.value = [...workItems.value.slice(0, idx), { ...workItems.value[idx], name: newName }, ...workItems.value.slice(idx + 1)]
    }
  } else {
    const idx = items.value.findIndex((i) => i.id === id)
    if (idx !== -1) {
      items.value = [...items.value.slice(0, idx), { ...items.value[idx], name: newName }, ...items.value.slice(idx + 1)]
    }
  }
  renameTarget.value = null
  renameInputValue.value = ''
  removeRenameClickOutsideListener()
  const itemScope = item.scope ?? scope.value
  const body = { action: 'rename', scope: itemScope, id, new_name: newName }
  if (itemScope === 'work') body.work_id = item.work_id ?? selectedWorkId.value
  try {
    await supabaseService.manageCloudStorage(body)
  } catch (e) {
    if (isWork) {
      const idx = workItems.value.findIndex((i) => i.id === id)
      if (idx !== -1) {
        workItems.value = [...workItems.value.slice(0, idx), { ...workItems.value[idx], name: prevName }, ...workItems.value.slice(idx + 1)]
      }
    } else {
      const idx = items.value.findIndex((i) => i.id === id)
      if (idx !== -1) {
        items.value = [...items.value.slice(0, idx), { ...items.value[idx], name: prevName }, ...items.value.slice(idx + 1)]
      }
    }
    await dialog.alert(e.message || 'リネームに失敗しました', { title: 'エラー' })
  } finally {
    const next = new Set(pendingIds.value)
    next.delete(id)
    pendingIds.value = next
  }
}

