async function handleDelete(clearRefs = false) {
  if (!selectedItem.value?.id) return
  const item = selectedItem.value
  const isWork = scope.value === 'work'
  const confirmMsg = item.is_folder && !isWork && hasDescendantFolders(item.id)
    ? 'このフォルダにはサブフォルダが含まれています。全て削除しますか？'
    : '削除しますか？'
  if (!clearRefs && !await dialog.confirm(confirmMsg, { title: '確認' })) return
  const id = item.id
  const sc = scope.value
  pendingIds.value = new Set([...pendingIds.value, id])
  selectedItem.value = null
  const body = { action: item.is_folder ? 'delete_folder' : 'delete', scope: sc, id }
  if (isWork) body.work_id = item.work_id ?? selectedWorkId.value
  if (!item.is_folder && clearRefs) body.clear_refs = true
  try {
    await supabaseService.manageCloudStorage(body)
    if (isWork) {
      workItems.value = workItems.value.filter((i) => i.id !== id)
    } else {
      items.value = items.value.filter((i) => i.id !== id)
    }
    if (item.is_folder) {
      const parentId = item.parent_id ?? null
      if (currentFolderId.value === id) {
        currentFolderId.value = parentId
      }
      nextTick(() => {
        const arr = isWork ? workItems.value : items.value
        const parent = parentId ? arr.find((i) => i.id === parentId && (isWork ? i.work_id === item.work_id : (i.scope ?? sc) === sc)) ?? null : null
        selectedItem.value = parent
      })
      const nextExp = new Set(expandedFolderIds.value)
      nextExp.delete(id)
      expandedFolderIds.value = nextExp
      const nextChecked = new Set(checkedIds.value)
      nextChecked.delete(id)
      checkedIds.value = nextChecked
    }
  } catch (e) {
    const msg = e.message || '削除に失敗しました'
    if (!item.is_folder && isWork && msg.includes('レポートスロットで使用中')) {
      const ok = await dialog.confirm('このファイルは写真台帳で使用中です。\n参照を解除して削除しますか？', { title: '確認' })
      if (ok) {
        selectedItem.value = item
        await handleDelete(true)
        return
      }
    } else {
      await dialog.alert(msg, { title: 'エラー' })
    }
  } finally {
    const next = new Set(pendingIds.value)
    next.delete(id)
    pendingIds.value = next
  }
}

