async function downloadSingleFile(item) {
  if (!item?.id || item.is_folder) return
  let url = item.public_url || ''
  if (!url) {
    const s = item.scope ?? scope.value
    const body = { action: 'download', scope: s, id: item.id }
    if (s === 'work') body.work_id = item.work_id ?? selectedWorkId.value
    const res = await supabaseService.manageCloudStorage(body)
    url = res?.signed_url || ''
  }
  if (!url) throw new Error('ダウンロードURLの取得に失敗しました')
  const resp = await fetch(url)
  if (!resp.ok) throw new Error(`ダウンロードに失敗しました (HTTP ${resp.status})`)
  const blob = await resp.blob()
  const blobUrl = URL.createObjectURL(blob)
  const a = document.createElement('a')
  a.href = blobUrl
  a.download = item.name || 'download'
  a.click()
  URL.revokeObjectURL(blobUrl)
}

async function downloadFolderAsZip(item) {
  if (!item?.id || !item.is_folder) return
  const itemScope = item.scope ?? scope.value
  if (!canUseZipForScope(itemScope)) return
  const body = {
    action: 'download_zip',
    scope: itemScope,
    folder_id: item.id,
    create_share: false
  }
  if (itemScope === 'work') body.work_id = item.work_id ?? selectedWorkId.value
  const res = await supabaseService.manageCloudStorage(body)
  if (!res?.download_url) throw new Error('ZIPダウンロードURLの取得に失敗しました')
  await downloadFileFromUrl(res.download_url, `${item.name || 'download'}.zip`)
}

