function canUseZipForScope(sc) {
  return typeof sc === 'string' && sc.length > 0
}

function canCreateShareForScope(sc) {
  return sc === 'contractor' || sc === 'personal'
}

function isShareExpired(expiresAt) {
  if (!expiresAt) return false
  const d = new Date(expiresAt)
  if (isNaN(d.getTime())) return false
  return d.getTime() < Date.now()
}

function formatShareExpiry(expiresAt) {
  if (!expiresAt) return '—'
  try {
    const d = new Date(expiresAt)
    if (isNaN(d.getTime())) return String(expiresAt)
    return d.toLocaleString('ja-JP')
  } catch {
    return String(expiresAt)
  }
}

async function downloadFileFromUrl(url, fileName) {
  const response = await fetch(url)
  if (!response.ok) {
    throw new Error(`ZIPのダウンロードに失敗しました (HTTP ${response.status})`)
  }
  const blob = await response.blob()
  const blobUrl = URL.createObjectURL(blob)
  const a = document.createElement('a')
  a.href = blobUrl
  a.download = fileName || 'download.zip'
  a.click()
  URL.revokeObjectURL(blobUrl)
}

