async function createFolder() {
  const name = newFolderName.value.trim()
  if (!name) return
  createFolderLoading.value = true
  const parentId = currentFolderId.value

  if (scope.value === 'work' && selectedWorkId.value) {
    const tempId = 'pending-folder-' + Date.now()
    const optimisticFolder = {
      id: tempId,
      parent_id: parentId,
      scope: 'work',
      name,
      is_folder: true,
      created_at: null,
      work_id: selectedWorkId.value
    }
    workItems.value = [optimisticFolder, ...workItems.value]
    pendingIds.value = new Set([...pendingIds.value, tempId])
    newFolderName.value = ''
    try {
      const res = await supabaseService.manageCloudStorage({
        action: 'create_folder',
        scope: 'work',
        work_id: selectedWorkId.value,
        parent_id: parentId,
        name
      })
      const folderId = res?.folder?.id
      if (folderId) {
        await supabaseService.manageCloudStorage({
          action: 'commit',
          scope: 'work',
          work_id: selectedWorkId.value,
          ids: [folderId]
        })
      }
      if (folderId && res?.folder) {
        const idx = workItems.value.findIndex((i) => i.id === tempId)
        if (idx !== -1) {
          const newFolder = { ...optimisticFolder, id: folderId, created_at: res.folder.created_at ?? null }
          workItems.value = [newFolder, ...workItems.value.filter((i) => i.id !== tempId)]
        }
        expandedFolderIds.value = new Set([...expandedFolderIds.value, folderId])
      }
    } catch (e) {
      workItems.value = workItems.value.filter((i) => i.id !== tempId)
      await dialog.alert(e.message || 'フォルダの作成に失敗しました', { title: 'エラー' })
    } finally {
      createFolderLoading.value = false
      const next = new Set(pendingIds.value)
      next.delete(tempId)
      pendingIds.value = next
    }
    return
  }

  const tempId = 'pending-folder-' + Date.now()
  const optimisticFolder = {
    id: tempId,
    parent_id: parentId,
    scope: scope.value,
    name,
    is_folder: true,
    created_at: null,
    size_bytes: null
  }
  items.value = [optimisticFolder, ...items.value]
  pendingIds.value = new Set([...pendingIds.value, tempId])
  newFolderName.value = ''
  try {
    const res = await supabaseService.manageCloudStorage({
      action: 'create_folder',
      scope: scope.value,
      parent_id: parentId,
      name
    })
    const folderId = res?.folder?.id
    if (folderId) {
      await supabaseService.manageCloudStorage({
        action: 'commit',
        scope: scope.value,
        ids: [folderId]
      })
    }
    if (folderId && res?.folder) {
      const idx = items.value.findIndex((i) => i.id === tempId)
      if (idx !== -1) {
        const newFolder = { ...optimisticFolder, id: folderId, created_at: res.folder.created_at ?? null }
        items.value = [newFolder, ...items.value.filter((i) => i.id !== tempId)]
      }
      expandedFolderIds.value = new Set([...expandedFolderIds.value, folderId])
    }
  } catch (e) {
    items.value = items.value.filter((i) => i.id !== tempId)
    await dialog.alert(e.message || 'フォルダの作成に失敗しました', { title: 'エラー' })
  } finally {
    createFolderLoading.value = false
    const next = new Set(pendingIds.value)
    next.delete(tempId)
    pendingIds.value = next
  }
}

/** サーバー側の制限に合わせるアップロード最大サイズ（50MB） */
const MAX_FILE_SIZE = 50 * 1024 * 1024

/** 同時アップロード数・コピー並列数 */
const UPLOAD_CONCURRENCY = 10

/** 実行系・セキュリティリスクのためアップロード禁止の拡張子（エッジ関数と同期） */
const BLOCKED_EXTENSIONS = new Set([
  'exe', 'msi', 'bat', 'cmd', 'com', 'pif', 'scr',
  'ps1', 'psm1', 'psd1',
  'sh', 'bash', 'zsh',
  'vbs', 'vbe', 'ws', 'wsf', 'wsh', 'jse',
  'js', 'mjs', 'cjs',
  'jar', 'war', 'class',
  'py', 'pyc', 'pyw',
  'rb', 'pl', 'pm', 'php', 'phtml', 'phar',
  'asp', 'aspx', 'asa', 'cer', 'cdx',
  'jsp', 'jspx',
  'hta',
  'reg', 'cpl', 'msc',
  'lnk', 'scf', 'inf', 'url',
  'dll', 'so', 'dylib'
])

function getFileExtension(name) {
  const idx = (name || '').lastIndexOf('.')
  if (idx === -1) return ''
  return (name.slice(idx + 1).trim().toLowerCase() || '')
}

/** クラウドストレージタブのアップロード許可: 画像・PDF・ZIP・jww（拡張子または MIME で判定） */
const CLOUD_STORAGE_ALLOWED_IMAGE_EXT = new Set([
  'jpg',
  'jpeg',
  'png',
  'gif',
  'webp',
  'bmp',
  'tif',
  'tiff',
  'heic',
  'heif',
  'jpe',
  'jfif'
])

function isAllowedCloudStorageUpload(file) {
  if (!(file instanceof File)) return false
  const mt = String(file.type || '').toLowerCase()
  if (mt.startsWith('image/')) return true
  if (mt === 'application/pdf') return true
  if (mt === 'application/zip' || mt === 'application/x-zip-compressed') return true
  const ext = getFileExtension(file.name)
  if (ext === 'pdf' || ext === 'zip' || ext === 'jww') return true
  if (CLOUD_STORAGE_ALLOWED_IMAGE_EXT.has(ext)) return true
  return false
}

function filterAllowedCloudStorageUploads(fileList) {
  const allowed = []
  const rejected = []
  for (const f of fileList) {
    if (isAllowedCloudStorageUpload(f)) allowed.push(f)
    else rejected.push(f.name)
  }
  return { allowed, rejected }
}

function filterBlockedUploadFiles(fileList) {
  const allowed = []
  const blocked = []
  for (const f of fileList) {
    const ext = getFileExtension(f.name)
    if (BLOCKED_EXTENSIONS.has(ext)) {
      blocked.push(f.name)
    } else {
      allowed.push(f)
    }
  }
  return { allowed, blocked }
}

function filterOversizedFiles(fileList) {
  const allowed = []
  const oversized = []
  for (const f of fileList) {
    if (f.size > MAX_FILE_SIZE) {
      oversized.push(f.name)
    } else {
      allowed.push(f)
    }
  }
  return { allowed, oversized }
}

function getResolvedUploadFileName(file) {
  if (file.type?.startsWith('image/') || isHeicLikeFile(file)) {
    return resolveCameraPlaceholderUploadName(file.name, { outputExt: 'jpg' })
  }
  return file.name
}

function getExistingFileNamesInFolder(parentId = null) {
  const normParent = parentId ?? null
  const source = scope.value === 'work' ? workItems.value : items.value.filter((i) => i.scope === scope.value)
  return source
    .filter((i) => {
      if (i.is_folder) return false
      if (scope.value === 'work' && selectedWorkId.value && (i.work_id ?? selectedWorkId.value) !== selectedWorkId.value) {
        return false
      }
      const itemParent = i.parent_id ?? null
      return String(itemParent || '') === String(normParent || '')
    })
    .map((i) => i.name)
}

function getExistingFileNamesInCurrentFolder() {
  return getExistingFileNamesInFolder(currentFolderId.value ?? null)
}

/** ターゲットフォルダ内の既存ファイル一覧を取得（ローカル事前チェック用） */
function getExistingFilesInTargetFolder(targetScope, targetWorkId, targetParentId) {
  const normParent = targetParentId || null
  let source
  if (targetScope === 'work') {
    if (targetWorkId !== selectedWorkId.value) return null
    source = workItems.value
  } else {
    source = items.value
  }
  return source.filter((i) => {
    if (i.is_folder) return false
    if (i.scope !== targetScope) return false
    if (targetScope === 'work' && (i.work_id ?? selectedWorkId.value) !== targetWorkId) return false
    const p = i.parent_id ?? null
    return String(p || '') === String(normParent || '')
  }).map((i) => ({ id: i.id, name: i.name }))
}

function handleDrop(e) {
  isDragOver.value = false
  if (e.dataTransfer?.types?.includes(MOVE_DRAG_TYPE)) return
  void handleExternalDropOrFolder(e)
}

async function handleExternalDropOrFolder(e) {
  const inspected = inspectExternalDrop(e.dataTransfer)
  if (inspected.dropKind === 'error') {
    await dialog.alert(inspected.message, { title: 'エラー' })
    return
  }

  if (inspected.dropKind === 'folder') {
    if (scope.value !== 'work' || !selectedWorkId.value) {
      await dialog.alert(FOLDER_DROP_MESSAGES.WORK_SCOPE_ONLY, { title: 'エラー' })
      return
    }
    await handleExternalFolderDrop(inspected.entry)
    return
  }

  const files = Array.from(e.dataTransfer?.files || []).filter((f) => f instanceof File && !f.name.startsWith('.'))
  if (files.length === 0) return
  startUploadWithOverwriteCheck(files)
}

async function handleExternalFolderDrop(dirEntry) {
  const readResult = await readFlatFolderFiles(dirEntry)
  if (readResult.error) {
    await dialog.alert(readResult.error, { title: 'エラー' })
    return
  }

  const nameValidation = validateDroppedFolderName(dirEntry.name)
  if (!nameValidation.ok) {
    await dialog.alert(nameValidation.message, { title: 'エラー' })
    return
  }

  const { valid, excluded } = partitionCloudStorageUploadFiles(readResult.files)
  if (valid.length === 0) {
    await dialog.alert(FOLDER_DROP_MESSAGES.NO_UPLOADABLE_FILES, { title: 'エラー' })
    return
  }

  const shouldContinue = await confirmContinueWithoutExcluded(dialog, excluded)
  if (!shouldContinue) return

  uploadProgress.value = { current: 0, total: valid.length }
  try {
    const parentIdForSearch = currentFolderId.value ?? null
    const workFolders = workItems.value
      .filter((i) => i.is_folder)
      .map((i) => ({
        id: i.id,
        name: i.name,
        label: i.name,
        parent_id: i.parent_id ?? null
      }))

    const targetFolderId = await resolveFolderTargetId({
      folders: workFolders,
      folderName: nameValidation.name,
      parentId: parentIdForSearch,
      createFolder: async (name, pid) => {
        const res = await supabaseService.manageCloudStorage({
          action: 'create_folder',
          scope: 'work',
          work_id: selectedWorkId.value,
          parent_id: pid,
          name
        })
        const folderId = res?.folder?.id
        if (folderId) {
          await supabaseService.manageCloudStorage({
            action: 'commit',
            scope: 'work',
            work_id: selectedWorkId.value,
            ids: [folderId]
          })
          const createdFolder = {
            id: folderId,
            parent_id: pid,
            scope: 'work',
            name,
            is_folder: true,
            created_at: res.folder?.created_at ?? null,
            work_id: selectedWorkId.value
          }
          workItems.value = [createdFolder, ...workItems.value.filter((i) => i.id !== folderId)]
          expandedFolderIds.value = new Set([...expandedFolderIds.value, folderId])
        }
        return { id: folderId }
      }
    })

    await startUploadWithOverwriteCheck(valid, { uploadParentId: targetFolderId })
  } catch (err) {
    await whileUploadOverlayPaused(() =>
      dialog.alert(err?.message || 'フォルダドロップのアップロードに失敗しました', { title: 'エラー' })
    )
    uploadProgress.value = { current: 0, total: 0 }
  }
}

async function startUploadWithOverwriteCheck(fileList, { uploadParentId } = {}) {
  if (fileList.length === 0) return
  const effectiveParentId = uploadParentId !== undefined
    ? uploadParentId
    : (currentFolderId.value ?? null)

  const { allowed: typeOk, rejected: typeRejected } = filterAllowedCloudStorageUploads(fileList)
  if (typeRejected.length > 0) {
    const { valid, excluded } = partitionCloudStorageUploadFiles(fileList)
    const onlyExcluded = excluded.filter((item) => item.reason === '画像・PDF・ZIP・jww以外')
    if (onlyExcluded.length === excluded.length && valid.length > 0) {
      const shouldContinue = await whileUploadOverlayPaused(() =>
        confirmContinueWithoutExcluded(dialog, excluded)
      )
      if (!shouldContinue) {
        if (uploadProgress.value.total > 0 && !uploadLoading.value) {
          uploadProgress.value = { current: 0, total: 0 }
        }
        return
      }
      return startUploadWithOverwriteCheck(valid, { uploadParentId: effectiveParentId })
    }
    await whileUploadOverlayPaused(() =>
      dialog.alert(
        `以下のファイルはアップロードできません（画像・PDF・ZIP・jwwのみ可）:\n${typeRejected.join('\n')}`,
        { title: 'エラー' }
      )
    )
    if (uploadProgress.value.total > 0 && !uploadLoading.value) {
      uploadProgress.value = { current: 0, total: 0 }
    }
    return
  }
  const { allowed: afterBlocked, blocked } = filterBlockedUploadFiles(typeOk)
  if (blocked.length > 0) {
    await whileUploadOverlayPaused(() =>
      dialog.alert(`以下のファイルはアップロード禁止です:\n${blocked.join('\n')}`, { title: 'エラー' })
    )
    if (uploadProgress.value.total > 0 && !uploadLoading.value) {
      uploadProgress.value = { current: 0, total: 0 }
    }
    return
  }
  const { allowed, oversized } = filterOversizedFiles(afterBlocked)
  if (oversized.length > 0) {
    const withoutOversized = afterBlocked.filter((f) => f.size <= MAX_FILE_SIZE)
    if (withoutOversized.length > 0) {
      const excluded = oversized.map((name) => ({ name, reason: '50MB超過' }))
      const shouldContinue = await whileUploadOverlayPaused(() =>
        confirmContinueWithoutExcluded(dialog, excluded)
      )
      if (!shouldContinue) {
        if (uploadProgress.value.total > 0 && !uploadLoading.value) {
          uploadProgress.value = { current: 0, total: 0 }
        }
        return
      }
      return startUploadWithOverwriteCheck(withoutOversized, { uploadParentId: effectiveParentId })
    }
    await whileUploadOverlayPaused(() =>
      dialog.alert(`以下のファイルは50MBを超えているためアップロードできません:\n${oversized.join('\n')}`, { title: 'エラー' })
    )
    if (uploadProgress.value.total > 0 && !uploadLoading.value) {
      uploadProgress.value = { current: 0, total: 0 }
    }
    return
  }
  if (allowed.length === 0) {
    if (uploadProgress.value.total > 0 && !uploadLoading.value) {
      uploadProgress.value = { current: 0, total: 0 }
    }
    return
  }
  const existingNames = new Set(getExistingFileNamesInFolder(effectiveParentId))
  const conflicts = allowed
    .map((f) => getResolvedUploadFileName(f))
    .filter((name) => existingNames.has(name))
  if (conflicts.length > 0) {
    overwriteModalType.value = 'upload'
    overwriteConflictNames.value = [...new Set(conflicts)]
    pendingUploadFiles.value = allowed
    pendingUploadParentId.value = uploadParentId
    showOverwriteModal.value = true
    return
  }
  await uploadFiles(allowed, { uploadParentId: effectiveParentId })
}

async function confirmSkipDuplicatesUpload() {
  const files = pendingUploadFiles.value
  const uploadParentId = pendingUploadParentId.value
  const conflictNames = new Set(overwriteConflictNames.value)
  showOverwriteModal.value = false
  overwriteConflictNames.value = []
  pendingUploadFiles.value = null
  pendingUploadParentId.value = undefined
  if (uploadProgress.value.total > 0 && !uploadLoading.value) {
    uploadProgress.value = { current: 0, total: 0 }
  }
  const filesToUpload = (files || []).filter((f) => !conflictNames.has(getResolvedUploadFileName(f)))
  if (filesToUpload.length === 0) {
    await dialog.alert('アップロードするファイルはありません', { title: 'お知らせ' })
    return
  }
  uploadProgress.value = { current: 0, total: filesToUpload.length }
  await uploadFiles(filesToUpload, {
    uploadParentId: uploadParentId !== undefined ? uploadParentId : (currentFolderId.value ?? null)
  })
}

async function confirmOverwrite() {
  const files = pendingUploadFiles.value
  const uploadParentId = pendingUploadParentId.value
  showOverwriteModal.value = false
  overwriteConflictNames.value = []
  pendingUploadFiles.value = null
  pendingUploadParentId.value = undefined
  if (files && files.length > 0) {
    await uploadFiles(files, {
      uploadParentId: uploadParentId !== undefined ? uploadParentId : (currentFolderId.value ?? null)
    })
  }
}

function cancelOverwrite() {
  showOverwriteModal.value = false
  overwriteConflictNames.value = []
  pendingUploadFiles.value = null
  pendingUploadParentId.value = undefined
  if (uploadProgress.value.total > 0 && !uploadLoading.value) {
    uploadProgress.value = { current: 0, total: 0 }
  }
}

function handleMobileFileSelected(e) {
  const input = e.target
  const files = Array.from(input?.files || []).filter((f) => f instanceof File && !f.name.startsWith('.'))
  if (input) input.value = ''
  if (files.length > 0) startUploadWithOverwriteCheck(files)
}

async function prepareImageForUpload(file) {
  if (!file.type?.startsWith('image/') && !isHeicLikeFile(file)) return { file, metadata: null }
  try {
    const { mainImage, thumbnail, sthumb, width, height, exifDateTime, isStandardAspectRatio } = await processImageForUpload(file)
    const uploadName = resolveCameraPlaceholderUploadName(file.name, { outputExt: 'jpg' })
    const toUpload = new File([mainImage], uploadName, { type: 'image/jpeg' })
    return {
      file: toUpload,
      metadata: { width, height, exifDateTime, isStandardAspectRatio },
      thumbnail,
      sthumb
    }
  } catch (error) {
    if (isHeicLikeFile(file)) {
      throw error
    }
    return { file, metadata: null, thumbnail: null, sthumb: null }
  }
}

async function uploadSingleFile(file, localThumbByFileId = null, uploadParentId = null) {
  let toUpload = file
  let metadata = null
  let thumbBlob = null
  let sthumbBlob = null
  if (file.type?.startsWith('image/') || isHeicLikeFile(file)) {
    const prepared = await prepareImageForUpload(file)
    toUpload = prepared.file
    metadata = prepared.metadata
    thumbBlob = prepared.thumbnail
    sthumbBlob = prepared.sthumb
  }
  const formData = new FormData()
  formData.append('action', 'upload')
  formData.append('scope', scope.value)
  const parentForUpload = uploadParentId !== null && uploadParentId !== undefined
    ? uploadParentId
    : (currentFolderId.value ?? '')
  formData.append('parent_id', parentForUpload ?? '')
  if (scope.value === 'work' && selectedWorkId.value) formData.append('work_id', selectedWorkId.value)
  formData.append('file', toUpload)
  if (toUpload.type?.startsWith('image/')) {
    if (thumbBlob) formData.append('thumbnail', thumbBlob, 'thumb.jpg')
    if (sthumbBlob) formData.append('sthumb', sthumbBlob, 'sthumb.jpg')
    if (metadata) {
      formData.append('file_metadata', JSON.stringify([{
        originalFileName: toUpload.name,
        width: metadata.width ?? null,
        height: metadata.height ?? null,
        exifDateTime: metadata.exifDateTime ?? null,
        isStandardAspectRatio: metadata.isStandardAspectRatio ?? false
      }]))
    }
  }
  const res = await supabaseService.uploadCloudStorageFiles(formData)
  const ids = res?.uploaded?.map((u) => u.id) || []
  const embed =
    thumbBlob instanceof Blob && thumbBlob.size > 0 ? thumbBlob : null
  if (localThumbByFileId && embed) {
    for (const id of ids) {
      localThumbByFileId.set(id, embed)
    }
  }
  return ids
}

async function uploadFiles(fileList, { uploadParentId } = {}) {
  if (fileList.length === 0) return
  const list = Array.from(fileList)
  const effectiveParentId = uploadParentId !== undefined
    ? uploadParentId
    : (currentFolderId.value ?? null)
  const localThumbByFileId = new Map()
  uploadProgress.value = { current: 0, total: list.length }
  uploadLoading.value = true
  const uploadedIds = []
  let completed = 0
  try {
    for (let i = 0; i < list.length; i += UPLOAD_CONCURRENCY) {
      const chunk = list.slice(i, i + UPLOAD_CONCURRENCY)
      const results = await Promise.all(chunk.map((f) => uploadSingleFile(f, localThumbByFileId, effectiveParentId)))
      for (const ids of results) {
        uploadedIds.push(...ids)
      }
      completed = Math.min(i + chunk.length, list.length)
      uploadProgress.value = { current: completed, total: list.length }
    }
    if (uploadedIds.length > 0) {
      const commitBody = { action: 'commit', scope: scope.value, ids: uploadedIds }
      if (scope.value === 'work' && selectedWorkId.value) commitBody.work_id = selectedWorkId.value
      await supabaseService.manageCloudStorage(commitBody)
      if (scope.value === 'work' && selectedWorkId.value) {
        try {
          const wid = selectedWorkId.value
          const list = await supabaseService.getWorkFileFolderList(wid)
          let workKind = null
          let housingDetailId = null
          try {
            const w = await indexedDBService.getWorkById(wid)
            if (w) {
              workKind = w.kind ?? null
              if (w.housing_detail_id != null && w.housing_detail_id !== '') {
                housingDetailId = w.housing_detail_id
              }
            }
          } catch {
            /* App と同様、未取得時は Edge が works から補完 */
          }
          if (workKind == null && selectedWork.value?.kind) {
            workKind = selectedWork.value.kind
          }
          if ((housingDetailId == null || housingDetailId === '') && selectedWork.value?.housing_detail_id) {
            const hid = selectedWork.value.housing_detail_id
            if (hid != null && hid !== '') housingDetailId = hid
          }
          const canRunEmbedding = !props.isMobile && workKind === 'large'
          if (canRunEmbedding) {
            const targetFolderIdSet = new Set(
              (list.folders || [])
                .filter((fo) => ['施工前', '施工後'].includes(String(fo?.name || '').trim()) && fo?.id)
                .map((fo) => String(fo.id))
            )
            const uploadedIdSet = new Set(uploadedIds.map((id) => String(id)))
            const embedTargetCount = (list.files || []).filter((f) => {
              if (!uploadedIdSet.has(String(f?.id))) return false
              const parentId = String(f?.work_category_id ?? f?.folder_id ?? '')
              if (!targetFolderIdSet.has(parentId)) return false
              const mime = String(f?.mime_type || '').toLowerCase()
              if (mime.startsWith('image/')) return true
              const fileName = String(f?.original_name || f?.name || '').toLowerCase()
              const ext = fileName.split('.').pop()
              return ['jpg', 'jpeg', 'png', 'gif', 'webp', 'bmp'].includes(ext)
            }).length
            const shouldGenerate = embedTargetCount > 0
              ? await whileUploadOverlayPaused(() =>
                dialog.confirm('この画像で類似画像検索値の生成を行いますか？', { title: '確認' })
              )
              : false
            if (shouldGenerate) {
              uploadAfterPutPhase.value = true
              await supabaseService.runBatchPhotoEmbeddingsAfterCommit(wid, uploadedIds, {
                work_kind: workKind,
                housing_detail_id: housingDetailId,
                target_folder_names: ['施工前', '施工後'],
                folders: list.folders,
                files: list.files,
                localThumbByFileId
              })
            }
          }
        } catch (e) {
          console.warn('[CloudStorage] batch photo embeddings', e)
        }
      }
    }
    if (scope.value === 'work' && selectedWorkId.value) {
      await loadRefresh(selectedWorkId.value)
    } else {
      await loadList()
    }
  } catch (e) {
    await whileUploadOverlayPaused(() =>
      dialog.alert(e.message || 'アップロードに失敗しました', { title: 'エラー' })
    )
  } finally {
    uploadAfterPutPhase.value = false
    uploadProgress.value = { current: 0, total: 0 }
    uploadLoading.value = false
  }
}

</script>


