/**
 * App 集中ダイアログ（alert / confirm のブラウザ標準置き換え）
 *
 * 集約先: App.vue の AppDialogHost
 * タイトル tone: 成功=緑 / エラー=赤 / 確認=青 / 中断=黄 / その他=白
 * 同期キュー確認など特殊 UI は ConfirmModal を別途維持。
 *
 * confirm のカスタム本文:
 *   dialog.confirm('変換しますか？', {
 *     bodyKind: 'materialLaborPreview',
 *     preview: { before: [...], after: [...] }
 *   })
 */
import { reactive, inject } from 'vue'

export const DIALOG_KEY = Symbol('appDialog')

function inferTitleTone(title, type, options = {}) {
  if (options.titleTone) return options.titleTone
  const t = String(title ?? '').trim()
  if (t === '成功') return 'success'
  if (t === 'エラー') return 'error'
  if (t === '中断') return 'interrupt'
  if (t === '確認' || type === 'confirm') return 'confirm'
  return 'neutral'
}

export function createDialogState() {
  const state = reactive({
    open: false,
    type: 'alert',
    title: '',
    titleTone: 'neutral',
    message: '',
    /** 'text' | 'materialLaborPreview' など AppDialogHost 側のカスタム本文 */
    bodyKind: 'text',
    /** bodyKind 用ペイロード（例: { before: [], after: [] }） */
    preview: null,
    /** 確認モーダル内ラジオ（例: ユーザー単価コードのコピー/NU採番） */
    choiceOptions: null,
    choiceValue: null,
    messageClass: '',
    okText: 'OK',
    confirmText: 'はい',
    cancelText: 'いいえ'
  })

  function resetDialogBody() {
    state.bodyKind = 'text'
    state.preview = null
    state.choiceOptions = null
    state.choiceValue = null
    state.messageClass = ''
  }

  /** @type {Array<() => void>} */
  const queue = []
  /** @type {((value: unknown) => void) | null} */
  let pendingResolve = null

  /** @type {(() => void | Promise<void>) | null} */
  let pendingConfirmAction = null

  function transitionToLoading(title, message) {
    state.choiceOptions = null
    state.choiceValue = null
    state.preview = null
    state.messageClass = ''
    state.type = 'alert'
    state.title = title
    state.titleTone = 'neutral'
    state.message = String(message ?? '')
    state.bodyKind = 'loading'
    state.open = true
  }

  function transitionToSuccess(title, message) {
    state.choiceOptions = null
    state.choiceValue = null
    state.preview = null
    state.messageClass = ''
    state.type = 'alert'
    state.title = title
    state.titleTone = 'success'
    state.message = String(message ?? '')
    state.bodyKind = 'text'
    state.okText = 'OK'
    state.open = true
  }

  function transitionToError(title, message) {
    state.choiceOptions = null
    state.choiceValue = null
    state.preview = null
    state.messageClass = ''
    state.type = 'alert'
    state.title = title
    state.titleTone = 'error'
    state.message = String(message ?? '')
    state.bodyKind = 'text'
    state.okText = 'OK'
    state.open = true
  }

  function processQueue() {
    if (state.open || queue.length === 0) return
    const next = queue.shift()
    if (next) next()
  }

  function closeWith(result) {
    state.open = false
    const resolve = pendingResolve
    pendingResolve = null
    if (resolve) resolve(result)
    processQueue()
  }

  function openAlert(message, options = {}) {
    resetDialogBody()
    state.type = 'alert'
    state.title = options.title ?? 'お知らせ'
    state.titleTone = inferTitleTone(state.title, 'alert', options)
    state.message = String(message ?? '')
    state.bodyKind = options.bodyKind ?? 'text'
    state.preview = options.preview ?? null
    state.messageClass = options.messageClass ?? ''
    state.okText = options.okText ?? 'OK'
    state.open = true
  }

  function openConfirm(message, options = {}) {
    resetDialogBody()
    state.type = 'confirm'
    state.title = options.title ?? '確認'
    state.titleTone = inferTitleTone(state.title, 'confirm', options)
    state.message = String(message ?? '')
    state.bodyKind = options.bodyKind ?? 'text'
    state.preview = options.preview ?? null
    state.choiceOptions = options.choiceOptions ?? null
    state.choiceValue = options.defaultChoice ?? options.choiceOptions?.[0]?.value ?? null
    state.messageClass = options.messageClass ?? ''
    state.confirmText = options.confirmText ?? 'はい'
    state.cancelText = options.cancelText ?? 'いいえ'
    state.open = true
  }

  function alert(message, options = {}) {
    return new Promise((resolve) => {
      const run = () => {
        pendingResolve = () => resolve()
        openAlert(message, options)
      }
      if (state.open) queue.push(run)
      else run()
    })
  }

  function confirm(message, options = {}) {
    return new Promise((resolve) => {
      const run = () => {
        pendingResolve = (result) => {
          if (result === false) {
            resolve(false)
            return
          }
          if (state.choiceOptions?.length) {
            resolve({ ok: true, choice: state.choiceValue })
            return
          }
          resolve(true)
        }
        openConfirm(message, options)
      }
      if (state.open) queue.push(run)
      else run()
    })
  }

  function confirmThen(message, options = {}, asyncFn) {
    return new Promise((outerResolve) => {
      const run = () => {
        let settled = false
        const finish = (value) => {
          if (settled) return
          settled = true
          outerResolve(value)
          processQueue()
        }

        pendingResolve = (result) => {
          if (result === false) finish(false)
        }

        openConfirm(message, options)
        pendingConfirmAction = async () => {
          const choice = state.choiceOptions?.length ? state.choiceValue : undefined
          transitionToLoading(
            options.loadingTitle ?? '処理中',
            options.loadingMessage ?? '登録中...'
          )
          try {
            await asyncFn(choice)
            transitionToSuccess(
              options.successTitle ?? '成功',
              options.successMessage ?? 'アイテムを登録しました。'
            )
            pendingResolve = () => finish({ ok: true, choice })
          } catch (err) {
            console.error('[confirmThen]', err)
            transitionToError(
              options.errorTitle ?? 'エラー',
              options.errorMessage
                ?? `アイテムの登録に失敗しました: ${String(err?.message || err)}`
            )
            pendingResolve = () => finish(false)
          }
        }
      }
      if (state.open) queue.push(run)
      else run()
    })
  }

  function resolveOk() {
    if (pendingConfirmAction) {
      const action = pendingConfirmAction
      pendingConfirmAction = null
      void action()
      return
    }
    closeWith(true)
  }

  function resolveCancel() {
    pendingConfirmAction = null
    closeWith(state.type === 'confirm' ? false : undefined)
  }

  return {
    state,
    alert,
    confirm,
    confirmThen,
    resolveOk,
    resolveCancel
  }
}

export function useDialog() {
  const api = inject(DIALOG_KEY, null)
  if (!api) {
    console.warn('[useDialog] DIALOG_KEY not provided; falling back to window.alert/confirm')
    return {
      alert: (message) => {
        window.alert(String(message ?? ''))
        return Promise.resolve()
      },
      confirm: (message) => Promise.resolve(window.confirm(String(message ?? ''))),
      confirmThen: async (message, options = {}, asyncFn) => {
        const result = await (window.confirm(String(message ?? ''))
          ? { ok: true }
          : Promise.resolve(false))
        if (!result) return false
        try {
          await asyncFn(undefined)
          window.alert(String(options.successMessage ?? '完了しました'))
          return { ok: true }
        } catch (err) {
          window.alert(String(options.errorMessage ?? err?.message ?? err))
          return false
        }
      }
    }
  }
  return api
}
