<template>
  <div
    class="slot-item"
    :class="{ 
      'has-file': slot.file_id, 
      'empty': !slot.file_id, 
      'drag-over': isDragOver, 
      'disabled': disabled,
      'highlight-background': shouldHighlightBackground,
      'drag-over-left': dragOverZone === 'left',
      'drag-over-center': dragOverZone === 'center',
      'drag-over-right': dragOverZone === 'right',
      'extended-height': isSlotHeightExtended,
      'assign-mode': !!assignModeFileId,
      'reverse-assign-target': isReverseAssignTargetWhole,
      'glow-effect': isGlowing,
      'selected-glow': isSelected,
      'before-after-compare': beforeAfterCompareLayout
    }"
    :data-slot-id="slot.id"
    :draggable="!disabled && !isInputFocused && !slotItemMobile && !beforeAfterCompareLayout"
    @dragstart="handleDragStart"
    @dragend="handleDragEnd"
    @dragover.prevent="handleDragOver"
    @drop.prevent.stop="handleDrop"
    @dragleave="handleDragLeave"
  >
    <div class="slot-header">
      <div
        v-if="slotItemMobile && beforeAfterCompareLayout"
        class="slot-header-mobile slot-header-mobile--bacmp"
      >
        <select
          class="bacmp-room-label-select"
          :disabled="disabled"
          :value="bacmpRoomLabelSelectValue"
          title="ルームを選ぶとそのフォトワークの工事内容を表示（施工前に画像があっても、選択時はそのルームの内容を表示）"
          @change="onBacmpRoomLabelOrderChange"
        >
          <option
            v-for="opt in bacmpRoomLabelSelectOptions"
            :key="'bacmp-opt-m-' + (opt.value === null || opt.value === undefined ? 'unset' : String(opt.value)) + '-' + String(opt.label ?? '')"
            :value="bacmpSelectOptionValue(opt)"
          >
            {{ opt.label }}
          </option>
        </select>
        <button
          class="insert-btn insert-btn-plus insert-btn-copy"
          :disabled="disabled"
          title="この行の下に施工前行を追加"
          @click="handleCompareInsertAfter"
        >
          ＋
        </button>
        <div class="bacmp-header-end-actions">
          <button
            type="button"
            class="insert-btn similar-search-btn"
            :class="{ 'similar-search-btn-missing': isSimilarEmbeddingMissing }"
            :disabled="disabled || !slot.file_id || similarActionBusy || isSimilarTabDisabledForWorkKind || isSimilarSearchDisabledForAssignedFolder"
            :title="similarButtonTitle"
            @click="handleSimilarButtonClick"
          >
            <svg viewBox="0 0 24 24" width="14" height="14" fill="none" xmlns="http://www.w3.org/2000/svg" aria-hidden="true">
              <path d="M15.7955 15.8111L21 21M18 10.5C18 14.6421 14.6421 18 10.5 18C6.35786 18 3 14.6421 3 10.5C3 6.35786 6.35786 3 10.5 3C14.6421 3 18 6.35786 18 10.5Z" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"/>
            </svg>
          </button>
          <button
            class="delete-slot-btn bacmp-delete-right"
            @click.stop="handleDeleteSlot"
            :disabled="disabled"
            title="この行を一覧から外す"
          >
            ✕
          </button>
        </div>
      </div>

      <!-- スマホ: 「TOP / ページ-スロット / コピー＋ / 1 / フェーズ / ✕」を1行に -->
      <div v-else-if="slotItemMobile" class="slot-header-mobile">
        <button
          type="button"
          class="break-before-toggle"
          :class="{ 'is-active': localBreakBefore }"
          :disabled="disabled"
          title="ページ先頭（TOP）"
          :aria-pressed="localBreakBefore"
          aria-label="ページ先頭（TOP）"
          @click.stop="toggleBreakBefore"
        >
          <svg class="break-before-bookmark-icon" viewBox="0 0 24 24" width="17" height="17" aria-hidden="true" focusable="false">
            <path
              d="M19 21l-7-5-7 5V5a2 2 0 0 1 2-2h10a2 2 0 0 1 2 2v16z"
              :fill="localBreakBefore ? 'currentColor' : 'none'"
              :stroke="localBreakBefore ? 'none' : 'currentColor'"
              stroke-width="2"
              stroke-linecap="round"
              stroke-linejoin="round"
            />
          </svg>
        </button>

        <div class="slot-number">
          <span 
            class="page-number" 
            :class="{ 'page-number-red': shouldHighlightPageNumber }"
          >
            {{ getCircledNumber(slot.pageNumber || 1) }}
          </span>-<span 
            class="slot-number-value"
            :class="{ 
              'slot-number-red': shouldHighlightPageNumber || shouldHighlightSlotNumber 
            }"
          >
            {{ getCircledNumber(slot.slotNumberInPage || (slot.displayIndex + 1)) }}
          </span>
        </div>

        <button
          class="insert-btn insert-btn-plus insert-btn-copy"
          :disabled="disabled"
          title="空のスロットを挿入（カテゴリー・ファイルID以外をコピー）"
          @click="handleInsertPlusWithCopy"
        >
          <svg xmlns="http://www.w3.org/2000/svg" width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round">
            <rect x="9" y="9" width="13" height="13" rx="2" ry="2"></rect>
            <path d="M5 15H4a2 2 0 0 1-2-2V4a2 2 0 0 1 2-2h9a2 2 0 0 1 2 2v1"></path>
          </svg>
        </button>

        <button
          class="insert-btn insert-btn-plus"
          :disabled="disabled"
          title="空のスロットを1つ挿入"
          @click="handleInsertPlus"
        >
          1
        </button>

        <select
          v-model="localWorkPhaseId"
          @change="handleWorkPhaseChange"
          class="mobile-phase-select"
          :disabled="disabled"
        >
          <option 
            v-for="phase in workPhases" 
            :key="phase.id" 
            :value="phase.id"
          >
            {{ phase.label || phase.name || `Phase ${phase.id}` }}
          </option>
        </select>

        <button
          class="delete-slot-btn"
          @click.stop="handleDeleteSlot"
          :disabled="disabled"
          title="スロットを削除"
        >
          ✕
        </button>
      </div>

      <!-- PC: 既存UI -->
      <template v-else-if="!beforeAfterCompareLayout">
        <!-- ページ先頭（TOP）: しおりトグル -->
        <button
          type="button"
          class="break-before-toggle"
          :class="{ 'is-active': localBreakBefore }"
          :disabled="disabled"
          title="ページ先頭（TOP）"
          :aria-pressed="localBreakBefore"
          aria-label="ページ先頭（TOP）"
          @click.stop="toggleBreakBefore"
        >
          <svg class="break-before-bookmark-icon" viewBox="0 0 24 24" width="17" height="17" aria-hidden="true" focusable="false">
            <path
              d="M19 21l-7-5-7 5V5a2 2 0 0 1 2-2h10a2 2 0 0 1 2 2v16z"
              :fill="localBreakBefore ? 'currentColor' : 'none'"
              :stroke="localBreakBefore ? 'none' : 'currentColor'"
              stroke-width="2"
              stroke-linecap="round"
              stroke-linejoin="round"
            />
          </svg>
        </button>

        <!-- 複数選択チェックボックス -->
        <label class="multi-select-checkbox" title="複数選択">
          <input 
            type="checkbox" 
            :checked="isSelected" 
            @change="handleSelectionChange"
            @click.stop
            :disabled="disabled"
          />
          <span class="multi-select-label-text">選択</span>
        </label>

        <!-- PC: スロット移動・コピー（ドロップゾーンと同等） -->
        <div v-if="!hideSlotActionMenu" class="slot-action-menu-wrap">
          <button
            ref="slotActionMenuTriggerRef"
            type="button"
            class="slot-action-menu-trigger"
            :title="slotActionMenuTriggerTitle"
            :disabled="disabled"
            aria-haspopup="true"
            :aria-expanded="showSlotActionMenu"
            @click.stop="toggleSlotActionMenu"
            @mousedown.stop
          >
            ⋯
          </button>
          <Teleport to="body">
            <div v-if="showSlotActionMenu" class="slot-action-menu-portal">
              <div
                class="slot-action-menu-backdrop"
                aria-hidden="true"
                @click="closeSlotActionMenu"
              />
              <ul
                class="slot-action-menu"
                role="menu"
                :style="{ left: slotActionMenuPos.x + 'px', top: slotActionMenuPos.y + 'px' }"
                @click.stop
              >
                <li role="none">
                  <button
                    type="button"
                    class="slot-action-menu-item"
                    role="menuitem"
                    :disabled="disabled || !slotActionMenuEnabled"
                    @click="emitSlotMenuAction('move-up')"
                  >
                    ここに上 ↑ 移動
                  </button>
                </li>
                <li role="none">
                  <button
                    type="button"
                    class="slot-action-menu-item"
                    role="menuitem"
                    :disabled="disabled || !slotActionMenuEnabled"
                    @click="emitSlotMenuAction('move-down')"
                  >
                    ここに下 ↓ 移動
                  </button>
                </li>
                <li role="none">
                  <button
                    type="button"
                    class="slot-action-menu-item"
                    role="menuitem"
                    :disabled="disabled || !slotActionMenuEnabled"
                    @click="emitSlotMenuAction('copy')"
                  >
                    ここにコピー
                  </button>
                </li>
                <li role="none">
                  <button
                    type="button"
                    class="slot-action-menu-item"
                    role="menuitem"
                    :disabled="disabled"
                    @click="emitSlotMenuAction('row-insert')"
                  >
                    行挿入
                  </button>
                </li>
                <li role="none">
                  <button
                    type="button"
                    class="slot-action-menu-item"
                    role="menuitem"
                    :disabled="disabled || !canUseColumnDeleteButton"
                    @click="emitSlotMenuAction('column-delete')"
                  >
                    行削除
                  </button>
                </li>
              </ul>
            </div>
          </Teleport>
        </div>
        
        <!-- ページ番号-スロット番号 -->
        <div class="slot-number">
          <span 
            class="page-number" 
            :class="{ 'page-number-red': shouldHighlightPageNumber }"
          >
            {{ getCircledNumber(slot.pageNumber || 1) }}
          </span>-<span 
            class="slot-number-value"
            :class="{ 
              'slot-number-red': shouldHighlightPageNumber || shouldHighlightSlotNumber 
            }"
          >
            {{ getCircledNumber(slot.slotNumberInPage || (slot.displayIndex + 1)) }}
          </span>
        </div>
        
        <!-- ボタン: ←コピー 6→の順で表示 -->
        <div class="slot-controls">
          <button 
            v-if="showMoveAndSimilarButtons"
            class="insert-btn" 
            :disabled="disabled || !canUseLeftButton"
            :class="{ 'disabled-btn': !canUseLeftButton }"
            title="現在のスロットの内容（画像以外）をページ番号（同じ）-スロット番号-3にコピー"
            @click="handleCopyLeft"
          >
            ←
          </button>
          <button 
            class="insert-btn insert-btn-plus insert-btn-copy" 
            :disabled="disabled"
            title="空のスロットを挿入（カテゴリー・ファイルID以外をコピー）"
            @click="handleInsertPlusWithCopy"
          >
            <svg xmlns="http://www.w3.org/2000/svg" width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round">
              <rect x="9" y="9" width="13" height="13" rx="2" ry="2"></rect>
              <path d="M5 15H4a2 2 0 0 1-2-2V4a2 2 0 0 1 2-2h9a2 2 0 0 1 2 2v1"></path>
            </svg>
          </button>
          <button
            class="insert-btn insert-btn-plus"
            :disabled="disabled"
            title="空のスロットを1つ挿入"
            @click="handleInsertPlus"
          >
            1
          </button>
          <button 
            class="insert-btn insert-btn-plus" 
            :disabled="disabled"
            title="空のスロットを6つ挿入"
            @click="handleInsertPlus6"
          >
            6
          </button>
          <button
            v-if="!hideRowInsertColumnDeleteButtons"
            class="insert-btn row-insert-btn"
            :disabled="disabled"
            title="行挿入（1行ずらす）"
            @click="handleRowInsert"
          >
            <svg viewBox="0 0 24 24" width="16" height="16" fill="none" xmlns="http://www.w3.org/2000/svg" aria-hidden="true">
              <rect x="3" y="4" width="18" height="2" rx="1" fill="currentColor"/>
              <rect x="3" y="10" width="18" height="2" rx="1" fill="currentColor"/>
              <path d="M12 20V13.5" stroke="currentColor" stroke-width="2" stroke-linecap="round"/>
              <path d="M8.75 16.75L12 20L15.25 16.75" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"/>
            </svg>
          </button>
          <button 
            v-if="showMoveAndSimilarButtons"
            class="insert-btn" 
            :disabled="disabled || !canUseRightButton"
            :class="{ 'disabled-btn': !canUseRightButton }"
            title="現在のスロットの内容（画像以外）をページ番号（同じ）-スロット番号+3にコピー"
            @click="handleCopyRight"
          >
            →
          </button>
          <button
            class="insert-btn similar-search-btn"
            :class="{ 'similar-search-btn-missing': isSimilarEmbeddingMissing }"
            :disabled="disabled || !slot.file_id || similarActionBusy || isSimilarTabDisabledForWorkKind || isSimilarSearchDisabledForAssignedFolder"
            :title="similarButtonTitle"
            @click="handleSimilarButtonClick"
          >
            <svg viewBox="0 0 24 24" width="14" height="14" fill="none" xmlns="http://www.w3.org/2000/svg" aria-hidden="true">
              <path d="M15.7955 15.8111L21 21M18 10.5C18 14.6421 14.6421 18 10.5 18C6.35786 18 3 14.6421 3 10.5C3 6.35786 6.35786 3 10.5 3C14.6421 3 18 6.35786 18 10.5Z" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"/>
            </svg>
          </button>
        </div>
        
        <!-- フェーズセレクト -->
        <div class="slot-header-phase">
          <select 
            v-model="localWorkPhaseId" 
            @focus="isInputFocused = true"
            @blur="isInputFocused = false"
            @change="handleWorkPhaseChange"
            class="work-phase-select-header"
            :disabled="disabled"
          >
            <option 
              v-for="phase in workPhases" 
              :key="phase.id" 
              :value="phase.id"
            >
              {{ phase.label || phase.name || `Phase ${phase.id}` }}
            </option>
          </select>
        </div>
        
        <!-- カテゴリーインプット -->
        <div class="slot-header-category">
          <input
            v-model="localCaption"
            @keydown.enter="blurInputOnEnterWhenNotComposing"
            @focus="isInputFocused = true"
            @blur="isInputFocused = false; handleCaptionChange()"
            type="text"
            class="caption-input-header"
            placeholder="カテゴリー"
            :disabled="disabled"
          />
        </div>
        
        <!-- 削除ボタン -->
        <button
          v-if="!hideRowInsertColumnDeleteButtons"
          class="delete-column-btn"
          @click.stop="handleDeleteColumn"
          :disabled="disabled || !canUseColumnDeleteButton"
          :class="{ 'disabled-btn': !canUseColumnDeleteButton }"
          title="左列のこの行を削除（対応する右列も削除）"
        >
          <svg class="delete-column-icon" viewBox="0 0 24 24" aria-hidden="true" focusable="false">
            <path d="M7 12H20" />
            <path d="M5.2 8.4L11.2 15.6" />
            <path d="M11.2 8.4L5.2 15.6" />
          </svg>
        </button>
        <button
          class="delete-slot-btn"
          @click.stop="handleDeleteSlot"
          :disabled="disabled"
          title="スロットを削除"
        >
          ✕
        </button>
      </template>

      <template v-else>
        <div class="slot-header-bacmp-pc">
          <div class="bacmp-header-tail">
            <select
              class="bacmp-room-label-select"
              :disabled="disabled"
              :value="bacmpRoomLabelSelectValue"
              title="ルームを選ぶとそのフォトワークの工事内容を表示（施工前に画像があっても、選択時はそのルームの内容を表示）"
              @change="onBacmpRoomLabelOrderChange"
            >
              <option
                v-for="opt in bacmpRoomLabelSelectOptions"
                :key="'bacmp-opt-' + (opt.value === null || opt.value === undefined ? 'unset' : String(opt.value)) + '-' + String(opt.label ?? '')"
                :value="bacmpSelectOptionValue(opt)"
              >
                {{ opt.label }}
              </option>
            </select>
            <button
              class="insert-btn insert-btn-plus insert-btn-copy"
              :disabled="disabled"
              title="この行の下に施工前行を追加"
              @click="handleCompareInsertAfter"
            >
              ＋
            </button>
          </div>
          <div class="bacmp-header-end-actions">
            <button
              type="button"
              class="insert-btn similar-search-btn"
              :class="{ 'similar-search-btn-missing': isSimilarEmbeddingMissing }"
              :disabled="disabled || !slot.file_id || similarActionBusy || isSimilarTabDisabledForWorkKind || isSimilarSearchDisabledForAssignedFolder"
              :title="similarButtonTitle"
              @click="handleSimilarButtonClick"
            >
              <svg viewBox="0 0 24 24" width="14" height="14" fill="none" xmlns="http://www.w3.org/2000/svg" aria-hidden="true">
                <path d="M15.7955 15.8111L21 21M18 10.5C18 14.6421 14.6421 18 10.5 18C6.35786 18 3 14.6421 3 10.5C3 6.35786 6.35786 3 10.5 3C14.6421 3 18 6.35786 18 10.5Z" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"/>
              </svg>
            </button>
            <button
              class="delete-slot-btn bacmp-delete-right"
              @click.stop="handleDeleteSlot"
              :disabled="disabled"
              title="この行を一覧から外す"
            >
              ✕
            </button>
          </div>
        </div>
      </template>
    </div>
    
    <!-- 3分割の表示（スロットをドラッグしている時だけ表示） -->
    <div v-if="isDragOver && dragOverZone && !beforeAfterCompareLayout" class="drag-zone-indicators">
      <div class="drag-zone-indicator drag-zone-left" :class="{ 'active': dragOverZone === 'left' }">
        <span class="drag-zone-icon">↑</span>
        <span class="drag-zone-label">移動</span>
      </div>
      <div class="drag-zone-indicator drag-zone-center" :class="{ 'active': dragOverZone === 'center' }">
        <span class="drag-zone-icon">⧉</span>
        <span class="drag-zone-label">コピー</span>
      </div>
      <div class="drag-zone-indicator drag-zone-right" :class="{ 'active': dragOverZone === 'right' }">
        <span class="drag-zone-icon">↓</span>
        <span class="drag-zone-label">移動</span>
      </div>
    </div>
    
    <div v-if="beforeAfterCompareLayout" class="slot-content slot-content--bacmp">
      <div ref="slotLeftRef" class="slot-left slot-left--bacmp">
        <div ref="slotCompareTwinImagesRef" class="slot-compare-twin-images">
          <div
            ref="slotBacmpBeforeCellRef"
            class="slot-bacmp-before-cell"
            :class="{ 'reverse-assign-target': isReverseAssignTargetBefore }"
          >
            <div
              v-if="slot.file_id && imageUrls[slot.file_id]"
              class="slot-image slot-image--bacmp-before"
              :class="{
                'non-standard-aspect': !isStandardAspectRatio(slot.file_id),
                'slot-image--thumb-selected': isSlotImageThumbSelected
              }"
              @click.stop="onBacmpBeforeImageZoneTap"
            >
              <img
                :src="imageUrls[slot.file_id]"
                :alt="getFileName(slot.file_id)"
                :style="{
                  cursor: 'pointer',
                  transform: `rotate(${getFileRotation(slot.file_id)}deg)`,
                  opacity: isStandardAspectRatio(slot.file_id) ? 1 : 0.3,
                  ...getImageStyle(slot.file_id)
                }"
                draggable="false"
                @error="handleImageError"
              />
              <div
                v-if="!isStandardAspectRatio(slot.file_id)"
                class="non-standard-mark"
                title="標準アスペクト比ではありません"
              >
                ✕
              </div>
              <button
                v-if="isSlotImageThumbSelected && isBacmpBeforeFileOutsideBeforeFolder"
                type="button"
                class="remove-button remove-button--bacmp-before"
                title="施工前の画像を外す"
                @click.stop="handleCompareClearBefore"
              >
                ✕
              </button>
            </div>
            <div v-else-if="slot.file_id && imageUrls[slot.file_id] === null" class="slot-image-error">
              <div class="error-icon">⚠️</div>
              <div class="error-text">読込失敗</div>
              <button
                class="reload-btn"
                type="button"
                @click.stop="handleReloadImage"
                :disabled="disabled"
                title="画像を再読み込み"
              >
                再読込
              </button>
            </div>
            <div v-else class="slot-empty slot-empty--bacmp-before" @click.stop="null">
              <button
                type="button"
                class="mobile-upload-btn mobile-upload-btn--bacmp"
                :disabled="disabled"
                title="未割当から選ぶか、割当モードの画像をここに割り当て"
                aria-label="施工前・写真割り当て"
                @click.stop="handleBacmpEmptyAssignClick('before')"
              >
                <span class="mobile-upload-btn-plus" aria-hidden="true">+</span>
              </button>
              <span class="empty-text empty-text--bacmp-label">{{
                isCompareNewBlankRow ? '施工前（任意）' : '施工前'
              }}</span>
            </div>
          </div>

          <div
            ref="slotBacmpAfterZoneRef"
            class="slot-bacmp-after-zone"
            :class="{
              'slot-bacmp-after-zone--active': compareImage2DragOver,
              'reverse-assign-target': isReverseAssignTargetAfter
            }"
            @dragenter.prevent="compareImage2DragOver = true"
            @dragover.prevent="compareImage2DragOver = true"
            @dragleave="onCompareImage2DragLeave"
            @drop.prevent.stop="onCompareImage2Drop"
          >
            <div
              v-if="compareAfterImageId && imageUrls[compareAfterImageId]"
              class="slot-image slot-image--bacmp-after"
              :class="{
                'non-standard-aspect': !isStandardAspectRatio(compareAfterImageId),
                'slot-image--thumb-selected': isBacmpAfterImageThumbSelected
              }"
              @click.stop="onBacmpAfterImageZoneTap"
            >
              <img
                :src="imageUrls[compareAfterImageId]"
                :alt="getFileName(compareAfterImageId)"
                :style="{
                  cursor: 'pointer',
                  transform: `rotate(${getFileRotation(compareAfterImageId)}deg)`,
                  opacity: isStandardAspectRatio(compareAfterImageId) ? 1 : 0.3,
                  ...getImageStyle(compareAfterImageId)
                }"
                draggable="false"
                @error="(e) => handleImageError(e, compareAfterImageId)"
              />
              <div
                v-if="!isStandardAspectRatio(compareAfterImageId)"
                class="non-standard-mark"
                title="標準アスペクト比ではありません"
              >
                ✕
              </div>
              <button
                v-if="isBacmpAfterImageThumbSelected"
                type="button"
                class="remove-button remove-button--bacmp-after"
                title="施工後の画像を外す"
                @click.stop="handleCompareClearAfter"
              >
                ✕
              </button>
            </div>
            <div
              v-else-if="compareAfterImageId && imageUrls[compareAfterImageId] === null"
              class="slot-image-error"
            >
              <div class="error-icon">⚠️</div>
              <div class="error-text">読込失敗</div>
              <button
                class="reload-btn"
                type="button"
                @click.stop="handleReloadImage(compareAfterImageId)"
                :disabled="disabled"
                title="画像を再読み込み"
              >
                再読込
              </button>
