<script setup>
import { ref, watch, computed, onMounted, onUnmounted, inject, nextTick } from 'vue'
import { useDialog } from '../composables/useDialog'
import { inspectExternalDrop, FOLDER_DROP_MESSAGES } from '../utils/folderDropUpload'
import SnippetContextMenu from './SnippetContextMenu.vue'
import {
  SUPPLEMENT_ROOM_LABEL_ORDER,
  BACMP_SELECT_VALUE_SUPPLEMENT,
  bacmpSelectOptionValue,
  bacmpRoomLabelOrderFromSelectValue
} from '../utils/photoWorkRoomLabelOrder.js'

const props = defineProps({
  slot: {
    type: Object,
    required: true
  },
  imageUrls: {
    type: Object,
    default: () => ({})
  },
  files: {
    type: Array,
    default: () => []
  },
  workId: {
    type: String,
    required: true
  },
  workKind: {
    type: String,
    default: null
  },
  workPhases: {
    type: Array,
    default: () => []
  },
  disabled: {
    type: Boolean,
    default: false
  },
  isLeftColumn: {
    type: Boolean,
    default: false
  },
  allSlots: {
    type: Array,
    default: () => []
  },
  isSlotDragging: {
    type: Boolean,
    default: false
  },
  customSnippets: {
    type: Array,
    default: () => []
  },
  snippetGroups: {
    type: Array,
    default: () => []
  },
  snippetItemsByGroup: {
    type: Object,
    default: () => ({})
  },
  isSelected: {
    type: Boolean,
    default: false
  },
  isSlotHeightExtended: {
    type: Boolean,
    default: false
  },
  isInstructionMode: {
    type: Boolean,
    default: false
  },
  instructionType: {
    type: String,
    default: 'number' // 'number' or 'content'
  },
  billingItems: {
    type: Array,
    default: () => []
  },
  isMobile: {
    type: Boolean,
    default: false
  },
  slotItemIsMobile: {
    type: Boolean,
    default: true
  },
  hideMoveSimilarButtons: {
    type: Boolean,
    default: false
  },
  hideRowInsertColumnDeleteButtons: {
    type: Boolean,
    default: false
  },
  hideSlotActionMenu: {
    type: Boolean,
    default: false
  },
  assignModeFileId: {
    type: String,
    default: null
  },
  isGlowing: {
    type: Boolean,
    default: false
  },
  /** PC: いずれかのスロットが選択されているときだけ⋯メニューを有効化 */
  slotActionMenuEnabled: {
    type: Boolean,
    default: true
  },
  similarEmbeddingStatusByFileId: {
    type: Object,
    default: () => ({})
  },
  similarActionBusy: {
    type: Boolean,
    default: false
  },
  beforeAfterCompareLayout: {
    type: Boolean,
    default: false
  },
  compareAfterFileId: {
    type: String,
    default: null
  },
  compareDroppedBillingLines: {
    type: Array,
    default: () => []
  },
  linksByFileIdForCompare: {
    type: Object,
    default: () => ({})
  },
  compareBeforeFolderId: {
    type: String,
    default: null
  },
  compareAfterFolderId: {
    type: String,
    default: null
  },
  bacmpRoomLabelSelectOptions: {
    type: Array,
    default: () => []
  },
  compareRoomLabelOrder: {
    validator: (v) => v === null || v === undefined || typeof v === 'number' || typeof v === 'string',
    default: null
  },
  /** 逆割当モードの割当先スロットID */
  reverseAssignModeSlotId: {
    type: [String, Number],
    default: null
  },
  /** 施工前後モードの逆割当: 'before' | 'after' | null */
  reverseCompareAssignZone: {
    type: String,
    default: null
  }
})

const dialog = useDialog()

const emit = defineEmits([
  'assign',
  'unassign',
  'reorder',
  'upload',
  'update',
  'insert',
  'copy',
  'delete',
  'column-delete',
  'file-click',
  'slot-move',
  'slot-swap',
  'slot-copy',
  'file-swap',
  'file-copy',
  'slot-drag-start',
  'slot-drag-end',
  'add-custom-snippet',
  'selection-change',
  'start-assign-from-slot',
  'drop-completed',
  'row-insert',
  'slot-action-menu',
  'open-similar-tab',
  'generate-similar-embedding',
  'compare-set-after-file',
  'compare-clear-after-file',
  'compare-clear-before-file',
  'compare-set-before-file',
  'compare-append-billing-line',
  'compare-delete-row',
  'compare-insert-after-row',
  'compare-room-label-order-change',
  'open-bacmp-comparison'
])

const isDragOver = ref(false)
const dragOverZone = ref(null) // 'left', 'center', 'right'
const isInputFocused = ref(false) // 入力欄にフォーカス中かどうか
const slotItemMobile = computed(() => props.isMobile && props.slotItemIsMobile)

const isReverseAssignTargetRow = computed(() => {
  const targetId = props.reverseAssignModeSlotId
  if (targetId === null || targetId === undefined || targetId === '') return false
  return String(targetId) === String(props.slot.id)
})

const isReverseAssignTargetBefore = computed(
  () =>
    isReverseAssignTargetRow.value &&
    (!props.reverseCompareAssignZone || props.reverseCompareAssignZone === 'before')
)

const isReverseAssignTargetAfter = computed(
  () => isReverseAssignTargetRow.value && props.reverseCompareAssignZone === 'after'
)

/** 通常スロット全体をハイライト（施工前後でゾーン指定がある場合はセル単位） */
const isReverseAssignTargetWhole = computed(
  () =>
    isReverseAssignTargetRow.value &&
    !props.beforeAfterCompareLayout &&
    !props.reverseCompareAssignZone
)

const showMoveAndSimilarButtons = computed(() => !props.hideMoveSimilarButtons)

const compareImage2DragOver = ref(false)
const showBacmpBillingDetailModal = ref(false)
const compareAfterImageId = computed(() => {
  const id = props.compareAfterFileId
  if (id == null || id === '') return null
  return String(id)
})

/** 未割当の document dragover 自動スクロール解除（@drop.stop で window に届かないとき用） */
const CLEAR_UNASSIGNED_FILE_DRAG_EVENT = 'clear-unassigned-file-drag-state'
function notifyClearUnassignedFileDragScroll() {
  try {
    window.dispatchEvent(new Event(CLEAR_UNASSIGNED_FILE_DRAG_EVENT))
  } catch {
    /* noop */
  }
}

const BACMP_AFTER_TWOCLICK_SUFFIX = '__bacmp_after'
const bacmpAfterTwoClickKey = computed(() =>
  props.slot?.id != null && props.slot?.id !== ''
    ? `${String(props.slot.id)}${BACMP_AFTER_TWOCLICK_SUFFIX}`
    : ''
)

const slotImageTwoClickSlotId = inject('slotGridSlotImageTwoClickSlotId', null)

const isSlotImageThumbSelected = computed(() =>
  Boolean(slotImageTwoClickSlotId && slotImageTwoClickSlotId.value === props.slot.id)
)

const isBacmpAfterImageThumbSelected = computed(() =>
  Boolean(
    slotImageTwoClickSlotId &&
    bacmpAfterTwoClickKey.value &&
    slotImageTwoClickSlotId.value === bacmpAfterTwoClickKey.value
  )
)

watch(compareAfterImageId, (fid) => {
  if (!fid && slotImageTwoClickSlotId?.value === bacmpAfterTwoClickKey.value) {
    slotImageTwoClickSlotId.value = null
  }
})

/** photo_work_links の UI 専用行（content に _pwPhotoChrome。読込時は写真タブで除外済みだが旧データ用） */
function isPwPhotoChromeLinkRow(L) {
  if (!L) return false
  if (String(L.external_code || '').trim() !== '0') return false
  const q = L.quantity
  const qn = q === '' || q == null ? null : Number(q)
  if (qn !== 0 && q !== 0) return false
  try {
    const o = JSON.parse(String(L.content || '{}'))
    return Boolean(o && o._pwPhotoChrome === true)
  } catch {
    return false
  }
}

/** ＋で追加した空行（施工前枠は施工前フォルダ外もドロップ可） */
const isCompareNewBlankRow = computed(
  () =>
    props.beforeAfterCompareLayout &&
    String(props.slot?.id || '').startsWith('bacmp-new-') &&
    !props.slot?.file_id
)

/** 施工前枠の画像が施工前フォルダ外（追加行など） */
const isBacmpBeforeFileOutsideBeforeFolder = computed(() => {
  const fid = props.slot?.file_id
  if (!fid || !props.compareBeforeFolderId) return false
  const file = (props.files || []).find((f) => String(f.id) === String(fid))
  if (!file) return false
  const parent = String(file.work_category_id ?? file.folder_id ?? '')
  return parent !== String(props.compareBeforeFolderId)
})

/** 施工前画像なし行: フォトワーク参照用マップキー。未選択は補足バケットと分離（補足内容を出さない） */
const BACMP_LINKS_KEY_UNSET = '__bacmp_room_unset__'

const bacmpPhotoLinksBucketKey = computed(() => {
  const raw = props.compareRoomLabelOrder
  const roomUnset = raw === null || raw === undefined || raw === ''
  /** 施工前画像ありかつルーム未選択のときだけ file_id バケット。それ以外はルーム（未選択は専用キー） */
  if (props.slot?.file_id && roomUnset) {
    return String(props.slot.file_id)
  }
  if (roomUnset) return BACMP_LINKS_KEY_UNSET
  const ord = Number(raw)
  if (!Number.isFinite(ord)) return BACMP_LINKS_KEY_UNSET
  if (ord === SUPPLEMENT_ROOM_LABEL_ORDER) return '__null_file__'
  return `__room_order__:${ord}`
})

const linksFromPhotoWorkForBacmp = computed(() => {
  const map = props.linksByFileIdForCompare || {}
  return map[bacmpPhotoLinksBucketKey.value] || []
})

/** select の表示値: 未設定は空白、補足は BACMP_SELECT_VALUE_SUPPLEMENT（DOM 順: 空白→補足→実ルーム） */
const bacmpRoomLabelSelectValue = computed(() => {
  const opts = Array.isArray(props.bacmpRoomLabelSelectOptions) ? props.bacmpRoomLabelSelectOptions : []
  const raw = props.compareRoomLabelOrder
  let selectVal = ''
  if (raw !== null && raw !== undefined && raw !== '') {
    const n = typeof raw === 'string' && (raw === 'null' || raw === 'undefined') ? NaN : Number(raw)
    if (Number.isFinite(n)) {
      selectVal =
        n === SUPPLEMENT_ROOM_LABEL_ORDER ? BACMP_SELECT_VALUE_SUPPLEMENT : String(n)
    }
  }
  const allowed = new Set(opts.map((o) => bacmpSelectOptionValue(o)))
  if (allowed.size === 0) return ''
  if (!allowed.has(selectVal)) {
    if (allowed.has('')) return ''
    if (allowed.has(BACMP_SELECT_VALUE_SUPPLEMENT)) return BACMP_SELECT_VALUE_SUPPLEMENT
    return [...allowed][0]
  }
  return selectVal
})

function onBacmpRoomLabelOrderChange(event) {
  const raw = event?.target?.value
  const order = bacmpRoomLabelOrderFromSelectValue(raw)
  emit('compare-room-label-order-change', {
    slotId: props.slot.id,
    order
  })
}

const BACMP_BILLING_EXTRA_HEADER = '【追加】'

/** 施工前後: ドロップ追加行（保存形式は code\\tdesc\\tcontent） */
function parseCompareDroppedBillingLine(line) {
  const s = String(line ?? '').trim()
  if (!s) return { code: '', desc: '', content: '' }
  if (s.includes('\t')) {
    const parts = s.split('\t')
    return {
      code: (parts[0] || '').trim(),
      desc: (parts[1] || '').trim(),
      content: (parts[2] || '').trim()
    }
  }
  const tokens = s.split(/\s+/).filter(Boolean)
  if (tokens.length >= 2) {
    return { code: tokens[0], desc: tokens.slice(1).join(' '), content: '' }
  }
  return { code: '', desc: s, content: '' }
}

/** 追加項目の表示（単価コードなし・登録工事の内容行と同型） */
function formatCompareDroppedBillingLineForPanel(line) {
  const { desc, content } = parseCompareDroppedBillingLine(line)
  if (!desc && !content) return ''
  if (content) return desc ? `${desc} 内容:${content}` : `内容:${content}`
  return desc
}

function formatCompareDroppedBillingLineForButton(line) {
  const { desc, content } = parseCompareDroppedBillingLine(line)
  if (desc) return `・${desc}`
  if (content) return `・内容:${content}`
  return ''
}

const compareBillingPanelText = computed(() => {
  const lines = []
  for (const L of linksFromPhotoWorkForBacmp.value) {
    if (isPwPhotoChromeLinkRow(L)) continue
    const code = String(L?.external_code || '').trim()
    const desc = String(L?.description || '').trim()
    const content = String(L?.content || '').trim()
    if (!code && !desc && !content) continue
    const head = [code, desc].filter(Boolean).join(' ')
    lines.push(content ? `${head} 内容:${content}` : head)
  }
  const dedup = [...new Set(lines)]
  const base = dedup.join('\n')
  const extraLines = (props.compareDroppedBillingLines || [])
    .map(formatCompareDroppedBillingLineForPanel)
    .filter(Boolean)
  const extraDedup = [...new Set(extraLines)]
  if (base && extraDedup.length) return `${base}\n\n${BACMP_BILLING_EXTRA_HEADER}\n${extraDedup.join('\n')}`
  if (extraDedup.length) return `${BACMP_BILLING_EXTRA_HEADER}\n${extraDedup.join('\n')}`
  if (base) return base
  const rawOrder = props.compareRoomLabelOrder
  const unset =
    rawOrder === null || rawOrder === undefined || rawOrder === ''
  if (unset) {
    if (props.slot?.file_id) {
      return '（施工前に紐づく登録工事。見積行をドロップで追加できます）'
    }
    return '（見積行をドロップで追加できます）'
  }
  if (props.slot?.file_id) {
    return '（選択したルームの登録工事がありません。見積行をドロップで追加できます）'
  }
  return '（施工前に紐づく登録工事。見積行をドロップで追加できます）'
})

/** 上記2種の案内文のみ赤表示（textarea / 詳細モーダル） */
const compareBillingPanelTextIsRedHint = computed(() => {
  const t = compareBillingPanelText.value
  return (
    t === '（施工前に紐づく登録工事。見積行をドロップで追加できます）' ||
    t === '（見積行をドロップで追加できます）'
  )
})

const hasCompareBillingRegisteredContent = computed(() => {
  const lines = []
  for (const L of linksFromPhotoWorkForBacmp.value) {
    if (isPwPhotoChromeLinkRow(L)) continue
    const code = String(L?.external_code || '').trim()
    const desc = String(L?.description || '').trim()
    const content = String(L?.content || '').trim()
    if (!code && !desc && !content) continue
    lines.push([code, desc].filter(Boolean).join(' '))
  }
  const dedup = [...new Set(lines)]
  const base = dedup.join('\n').trim()
  const extraHas = (props.compareDroppedBillingLines || []).some((line) =>
    Boolean(formatCompareDroppedBillingLineForPanel(line))
  )
  return Boolean(base || extraHas)
})

const compareBillingDetailButtonText = computed(() => {
  const descriptions = []
  for (const L of linksFromPhotoWorkForBacmp.value) {
    if (isPwPhotoChromeLinkRow(L)) continue
    const desc = String(L?.description || '').trim()
    if (desc) descriptions.push(`・${desc}`)
  }
  for (const raw of props.compareDroppedBillingLines || []) {
    const btn = formatCompareDroppedBillingLineForButton(raw)
    if (btn) descriptions.push(btn)
  }
  return [...new Set(descriptions)].join('\n')
})

