      emit('compare-set-after-file', { slotId: props.slot.id, fileId: data.fileId })
      scheduleBacmpDropResizeLog('onCompareImage2Drop', { droppedFileId: data.fileId })
    } catch {
      /* ignore */
    }
  } finally {
    notifyClearUnassignedFileDragScroll()
  }
}

function compareDropZoneFromEvent(event) {
  const t = event.target
  if (typeof t.closest !== 'function') return null
  if (t.closest('.slot-bacmp-after-zone')) return 'after'
  if (t.closest('.slot-right--bacmp')) return 'billing'
  if (t.closest('.slot-image--bacmp-before') || t.closest('.slot-empty--bacmp-before')) return 'before'
  return null
}

function handleCompareLayoutDrop(event) {
  event.preventDefault()
  try {
    const files = Array.from(event.dataTransfer?.files || [])
    if (files.length > 0) {
      void dialog.alert('画像は左のパネルからドロップしてください', { title: '中断' })
      resetDropVisualState()
      return
    }
    try {
      const dataStr = event.dataTransfer?.getData?.('text/plain') || ''
      if (!dataStr) {
        resetDropVisualState()
        return
      }
      const data = JSON.parse(dataStr)
      const zone = compareDropZoneFromEvent(event)

      if (data.type === 'billing-item' && zone === 'billing') {
        const code = String(data.external_code || '').trim()
        const desc = String(data.description || data.billing_description || '').trim()
        const content = String(data.content || '').trim()
        if (!code && !desc && !content) {
          resetDropVisualState()
          return
        }
        const line = [code, desc, content].join('\t')
        emit('compare-append-billing-line', { slotId: props.slot.id, line })
        emit('drop-completed', { targetSlotId: props.slot.id, operationType: 'billing', sourceSlotId: null })
        resetDropVisualState()
        return
      }

      if (data.type === 'file' && zone === 'after') {
        onCompareImage2Drop(event)
        resetDropVisualState()
        return
      }

      if (data.type === 'file' && zone === 'before' && !props.slot.file_id) {
        const file = resolveFileFromDragId(data.fileId)
        if (!file) {
          resetDropVisualState()
          return
        }
        if (!isCompareNewBlankRow.value && props.compareBeforeFolderId) {
          const parent = String(file.work_category_id ?? file.folder_id ?? '')
          if (parent !== String(props.compareBeforeFolderId)) {
            void dialog.alert('施工前フォルダの画像のみドロップできます', { title: '中断' })
            resetDropVisualState()
            return
          }
        }
        emit('compare-set-before-file', { slotId: props.slot.id, fileId: data.fileId })
        scheduleBacmpDropResizeLog('handleCompareLayoutDrop:before', { droppedFileId: data.fileId })
        resetDropVisualState()
        return
      }
    } catch (err) {
      console.error('[compare drop]', err)
    }
    resetDropVisualState()
  } finally {
    notifyClearUnassignedFileDragScroll()
  }
}

function handleEmptySlotAssignClick(compareZoneMarker = null) {
  if (props.disabled) return
  const zoneBefore =
    compareZoneMarker === 'before' || compareZoneMarker === 'compare-before'
  const zoneAfter =
    compareZoneMarker === 'after' || compareZoneMarker === 'compare-after'

  if (props.assignModeFileId) {
    const fid = String(props.assignModeFileId)
    if (zoneBefore) {
      emit('compare-set-before-file', { slotId: props.slot.id, fileId: fid })
    } else if (zoneAfter) {
      emit('compare-set-after-file', { slotId: props.slot.id, fileId: fid })
    } else {
      emit('assign', props.slot.id, fid)
    }
    return
  }

  if (props.beforeAfterCompareLayout && (zoneBefore || zoneAfter)) {
    if (zoneBefore && !props.slot.file_id) {
      emit('start-assign-from-slot', props.slot.id, 'compare-before')
    } else if (zoneAfter && !compareAfterImageId.value) {
      emit('start-assign-from-slot', props.slot.id, 'compare-after')
    }
    return
  }

  if (!props.slot.file_id) {
    const marker = zoneBefore
      ? 'compare-before'
      : zoneAfter
        ? 'compare-after'
        : compareZoneMarker
    emit('start-assign-from-slot', props.slot.id, marker)
  }
}

