function handleDragStart(event) {
  if (slotItemMobile.value) return
  if (props.beforeAfterCompareLayout) return
  if (slotImageTwoClickSlotId) {
    slotImageTwoClickSlotId.value = null
  }
  event.dataTransfer.effectAllowed = 'move'
  event.dataTransfer.setData('text/plain', JSON.stringify({
    type: 'slot',
    slotId: props.slot.id
  }))
  // スロットドラッグを識別するためのカスタムタイプを追加
  event.dataTransfer.setData('application/x-slot', '')
  // スロットドラッグ開始を親コンポーネントに通知
  emit('slot-drag-start')
}

function handleDragEnd(event) {
  if (slotItemMobile.value) return
  // スロットドラッグ終了を親コンポーネントに通知
  emit('slot-drag-end')
  resetDropVisualState()
}

function resetDropVisualState() {
  isDragOver.value = false
  dragOverZone.value = null
}

function handleDragOver(event) {
  if (slotItemMobile.value) return
  if (props.beforeAfterCompareLayout) {
    event.preventDefault()
    return
  }
  event.preventDefault()

  // ファイルがドラッグされている場合
  if (event.dataTransfer.types.includes('Files')) {
    isDragOver.value = true
    dragOverZone.value = null
    event.dataTransfer.dropEffect = 'copy'
    return
  }
  
  // スロットをドラッグしている時だけ3分割の表示を表示
  // application/x-slotが含まれている場合のみ、スロットのドラッグと判断
  if (event.dataTransfer.types.includes('application/x-slot')) {
    // dragoverイベントではgetData()を呼び出せないため、typesのみで判断
    // 自分自身へのドラッグかどうかの判定はdropイベントで行う
    isDragOver.value = true
    
    // 3分割の位置判定
    const rect = event.currentTarget.getBoundingClientRect()
    const x = event.clientX - rect.left
    const width = rect.width
    const third = width / 3
    
    if (x < third) {
      dragOverZone.value = 'left'
    } else if (x < third * 2) {
      dragOverZone.value = 'center'
    } else {
      dragOverZone.value = 'right'
    }
    
    event.dataTransfer.dropEffect = 'move'
  } else if (event.dataTransfer.types.includes('text/plain')) {
    // 未割当ファイルまたは比較アイテムのドラッグの場合
    // dragoverイベントではgetData()を呼び出せないため、typesのみで判断
    // すべてのtext/plainをドラッグ可能として扱う
    isDragOver.value = true
    dragOverZone.value = null
    event.dataTransfer.dropEffect = 'copy'
  } else {
    isDragOver.value = false
    dragOverZone.value = null
  }
}

function handleDragLeave(event) {
  if (slotItemMobile.value) return
  // relatedTargetがnullの場合はドロップの可能性があるので無視
  if (!event.relatedTarget) {
    return
  }
  // 子要素への移動を除外
  if (!event.currentTarget.contains(event.relatedTarget)) {
    resetDropVisualState()
  }
}

function handleDrop(event) {
  if (slotItemMobile.value) return
  event.preventDefault()

  const inspected = inspectExternalDrop(event.dataTransfer)
  if (inspected.dropKind === 'folder') {
    void dialog.alert(FOLDER_DROP_MESSAGES.SLOT, { title: 'エラー' })
    resetDropVisualState()
    return
  }
  if (inspected.dropKind === 'error') {
    void dialog.alert(inspected.message, { title: 'エラー' })
    resetDropVisualState()
    return
  }

  if (props.beforeAfterCompareLayout) {
    handleCompareLayoutDrop(event)
    return
  }
  
  // ファイルがドロップされた場合
  const files = Array.from(event.dataTransfer.files)
  if (files.length > 0) {
    // 2つ以上のファイルがドロップされた場合はアラートを出して処理を中断
    if (files.length > 1) {
      void dialog.alert('スロットには1つのファイルのみドロップできます。複数のファイルをドロップすることはできません。', { title: '中断' })
      resetDropVisualState()
      return
    }
    emit('upload', files, props.slot.id)
    emit('drop-completed', { targetSlotId: props.slot.id, operationType: 'upload', sourceSlotId: null })
    resetDropVisualState()
    return
  }

  // 既存のデータがドロップされた場合
  try {
    const dataStr = event.dataTransfer.getData('text/plain')
    const data = JSON.parse(dataStr)
    
    if (data.type === 'file') {
      // ファイルをスロットに割り当て
      emit('assign', props.slot.id, data.fileId)
      emit('drop-completed', { targetSlotId: props.slot.id, operationType: 'assign', sourceSlotId: null })
    } else if (data.type === 'billing-item') {
      // 比較アイテムをドロップ - 備考末尾にコードを追加
      const code = data.external_code
      if (code) {
        // 現在の備考の末尾に ${コード} + 改行 を追加
        const currentNote = localNote.value || ''
        const formattedCode = `\${${code}}`
        const newNote = currentNote ? `${currentNote}${formattedCode}\n` : `${formattedCode}\n`
        localNote.value = newNote
        // 変更を親に通知
        handleNoteChange()
      }
      emit('drop-completed', { targetSlotId: props.slot.id, operationType: 'billing', sourceSlotId: null })
    } else if (data.type === 'slot' && data.slotId !== props.slot.id) {
      // 3分割の処理 - dragOverZoneが設定されている場合はそれを使用、なければマウス位置から判定
      let zone = dragOverZone.value
      
      // dragOverZoneが設定されていない場合、マウス位置から判定
      if (!zone) {
        const rect = event.currentTarget.getBoundingClientRect()
        const x = event.clientX - rect.left
        const width = rect.width
        const third = width / 3
        
        if (x < third) {
          zone = 'left'
        } else if (x < third * 2) {
          zone = 'center'
        } else {
          zone = 'right'
        }
      }
      
      if (zone === 'left') {
        // 左側：移動 - ドラッグ先のスロットとその上のスロットのスロットインデックスの中間を計算
        emit('slot-move', data.slotId, props.slot.id, zone)
        emit('drop-completed', { targetSlotId: props.slot.id, operationType: 'move', sourceSlotId: data.slotId })
      } else if (zone === 'center') {
        // 真ん中：コピー - ファイルID、フェーズ、メモをコピー
        emit('slot-copy', data.slotId, props.slot.id)
        emit('drop-completed', { targetSlotId: props.slot.id, operationType: 'copy', sourceSlotId: data.slotId })
      } else if (zone === 'right') {
        // 右：↓移動 - ドラッグ先とその下のスロットの中間に移動
        emit('slot-swap', data.slotId, props.slot.id)
        emit('drop-completed', { targetSlotId: props.slot.id, operationType: 'move', sourceSlotId: data.slotId })
      }
    } else if (data.type === 'file-id' && data.fileId) {
      // ファイルIDのドラッグ&ドロップ
      const zone = dragOverZone.value || 'center'
      if (data.action === 'swap') {
        emit('file-swap', data.slotId, props.slot.id)
        emit('drop-completed', { targetSlotId: props.slot.id, operationType: 'file-swap', sourceSlotId: data.slotId })
      } else if (data.action === 'copy') {
        emit('file-copy', data.slotId, props.slot.id)
        emit('drop-completed', { targetSlotId: props.slot.id, operationType: 'file-copy', sourceSlotId: data.slotId })
      }
    }
    
    resetDropVisualState()
  } catch (err) {
    console.error('Drop error:', err)
    resetDropVisualState()
  }
}


