  return file?.original_name || file?.file_name || '画像'
}

function getFileRotation(fileId) {
  const file = props.files.find(f => f.id === fileId)
  return file ? (file.rotation || 0) : 0
}

function isStandardAspectRatio(fileId) {
  const file = props.files.find(f => f.id === fileId)
  return file ? (file.is_standard_aspect_ratio !== false) : true
}

function getCompareTwinGridGapPx() {
  const el = slotCompareTwinImagesRef.value
  if (!el || typeof getComputedStyle !== 'function') return 6
  const cs = getComputedStyle(el)
  const raw = cs.columnGap && cs.columnGap !== 'normal' ? cs.columnGap : cs.gap
  const v = parseFloat(raw)
  return Number.isFinite(v) ? v : 6
}

function getQuarterTurnCompareFrameWidth(fileId) {
  const fid = String(fileId ?? '')
  const afterId = compareAfterImageId.value ? String(compareAfterImageId.value) : ''
  const beforeId =
    props.slot?.file_id != null && props.slot?.file_id !== '' ? String(props.slot.file_id) : ''
  const zoneEl = slotBacmpAfterZoneRef.value
  const beforeEl = slotBacmpBeforeCellRef.value

  if (afterId && fid === afterId) {
    const w = Math.max(0, Number(slotBacmpAfterColumnWidth.value) || 0)
    if (w > 0) return w
    if (zoneEl && typeof zoneEl.clientWidth === 'number' && zoneEl.clientWidth > 0) return zoneEl.clientWidth
  }
  if (beforeId && fid === beforeId) {
    const w = Math.max(0, Number(slotLeftWidth.value) || 0)
    if (w > 0) return w
    if (beforeEl && typeof beforeEl.clientWidth === 'number' && beforeEl.clientWidth > 0) return beforeEl.clientWidth
  }
  const twin = slotCompareTwinImagesRef.value
  const twinW =
    twin && typeof twin.clientWidth === 'number' ? Math.max(0, twin.clientWidth) : 0
  if (twinW > 0) {
    const gapPx = getCompareTwinGridGapPx()
    return twinW > gapPx ? (twinW - gapPx) / 2 : twinW * 0.48
  }
  return 0
}

function getImageStyle(fileId) {
  // 画像エリア幅の変化（左パネル開閉・施工後の有無・ツイン列レイアウト）時に再計算を強制
  slotLeftResizeTick.value
  const rotation = ((Number(getFileRotation(fileId)) % 360) + 360) % 360
  const isQuarterTurn = rotation === 90 || rotation === 270

  if (isQuarterTurn) {
    let frameWidth = 0
    if (props.beforeAfterCompareLayout) {
      frameWidth = getQuarterTurnCompareFrameWidth(fileId)
    } else {
      frameWidth = Math.max(0, Number(slotLeftWidth.value) || 0)
    }
    const frameHeight = frameWidth > 0 ? frameWidth * (3 / 4) : 0
    if (frameWidth > 0 && frameHeight > 0) {
      return {
        width: `${frameHeight}px`,
        height: `${frameWidth}px`,
        maxWidth: 'none',
        maxHeight: 'none',
        objectFit: 'contain',
        objectPosition: 'center'
      }
    }
    // 幅未計測・0 のとき intrinsic で巨大化しない（ツイン列の Grid でも枠内に収める）
    if (props.beforeAfterCompareLayout) {
      return {
        width: '100%',
        height: '100%',
        maxWidth: '100%',
        maxHeight: '100%',
        objectFit: 'contain',
        objectPosition: 'center'
      }
    }
    return {
      width: 'auto',
      height: 'auto',
      maxWidth: 'none',
      maxHeight: 'none',
      objectFit: 'contain',
      objectPosition: 'center'
    }
  }

  return {
    width: '100%',
    height: '100%',
    objectFit: 'cover',
    objectPosition: 'center'
  }
}

/** 施工前後: ドロップ直後に参照している幅・getImageStyle をコンソールへ（[bacmp-drop] で検索） */
function logBacmpDropResizeDebug(source, extra = {}) {
  if (!props.beforeAfterCompareLayout) return
  const beforeId =
    props.slot?.file_id != null && props.slot?.file_id !== '' ? String(props.slot.file_id) : ''
  const afterId = compareAfterImageId.value ? String(compareAfterImageId.value) : ''
  const beforeEl = slotBacmpBeforeCellRef.value
  const zoneEl = slotBacmpAfterZoneRef.value
  const twinEl = slotCompareTwinImagesRef.value

  console.log('[bacmp-drop]', {
    source,
    slotId: props.slot.id,
    ...extra,
    props_slot_file_id: props.slot.file_id,
    props_compareAfterFileId: props.compareAfterFileId,
    compareAfterImageId_computed: compareAfterImageId.value,
    ref_slotLeftWidth: slotLeftWidth.value,
    ref_slotBacmpAfterColumnWidth: slotBacmpAfterColumnWidth.value,
    ref_slotLeftResizeTick: slotLeftResizeTick.value,
    dom_slotLeftRef_clientWidth: slotLeftRef.value?.clientWidth,
    dom_beforeCell_clientWidth: beforeEl?.clientWidth,
    dom_afterZone_clientWidth: zoneEl?.clientWidth,
    dom_twin_clientWidth: twinEl?.clientWidth,
    css_gapPx_from_computed: getCompareTwinGridGapPx(),
    getQuarterTurnCompareFrameWidth_before: beforeId ? getQuarterTurnCompareFrameWidth(beforeId) : null,
    getQuarterTurnCompareFrameWidth_after: afterId ? getQuarterTurnCompareFrameWidth(afterId) : null,
    rotation_before_deg: beforeId ? getFileRotation(beforeId) : null,
    rotation_after_deg: afterId ? getFileRotation(afterId) : null,
    getImageStyle_before: beforeId ? getImageStyle(beforeId) : null,
    getImageStyle_after: afterId ? getImageStyle(afterId) : null
  })
}

function scheduleBacmpDropResizeLog(source, extra = {}) {
  if (!props.beforeAfterCompareLayout) return
  nextTick(() => {
    nextTick(() => {
      requestAnimationFrame(() => {
        logBacmpDropResizeDebug(source, extra)
      })
    })
  })
}

// 数字を丸数字に変換（① ② ③ など）
function getCircledNumber(num) {
  const numValue = Number(num)
  if (numValue >= 1 && numValue <= 20) {
    // Unicode丸数字（①-⑳）
    return String.fromCharCode(0x245F + numValue)
  } else {
    // 20を超える場合は数字をそのまま返す（必要に応じて拡張可能）
    return numValue.toString()
  }
}

function blurInputOnEnterWhenNotComposing(event) {
  if (!event) return
  if (event.isComposing || event.keyCode === 229) return
  const native = event.nativeEvent
  if (native?.isComposing) return
  event.preventDefault()
  const target = event.target
  if (target && typeof target.blur === 'function') target.blur()
}

