function bindSlotLeftResizeObserver() {
  if (slotLeftResizeObserver) {
    slotLeftResizeObserver.disconnect()
    slotLeftResizeObserver = null
  }
  if (typeof ResizeObserver === 'undefined') return
  slotLeftResizeObserver = new ResizeObserver((entries) => {
    for (const entry of entries || []) {
      const target = entry?.target
      if (!target) continue
      if (props.beforeAfterCompareLayout && slotBacmpBeforeCellRef.value === target) {
        const measuredWidth =
          Number(entry?.contentRect?.width) ||
          (typeof target.clientWidth === 'number' ? target.clientWidth : 0) ||
          0
        if (measuredWidth > 0) slotLeftWidth.value = measuredWidth
      }
      if (props.beforeAfterCompareLayout && slotBacmpAfterZoneRef.value === target) {
        const w =
          Number(entry?.contentRect?.width) ||
          (typeof target.clientWidth === 'number' ? target.clientWidth : 0) ||
          0
        if (w > 0) slotBacmpAfterColumnWidth.value = w
      }
    }
    slotLeftResizeTick.value += 1
  })
  if (props.beforeAfterCompareLayout) {
    if (slotBacmpBeforeCellRef.value) slotLeftResizeObserver.observe(slotBacmpBeforeCellRef.value)
    if (slotBacmpAfterZoneRef.value) slotLeftResizeObserver.observe(slotBacmpAfterZoneRef.value)
    slotLeftWidth.value = Number(slotBacmpBeforeCellRef.value?.clientWidth) || 0
    slotBacmpAfterColumnWidth.value = Number(slotBacmpAfterZoneRef.value?.clientWidth) || 0
  } else {
    slotBacmpAfterColumnWidth.value = 0
    const left = slotLeftRef.value
    if (left) slotLeftResizeObserver.observe(left)
    slotLeftWidth.value = left ? Number(left.clientWidth) || 0 : 0
  }
  slotLeftResizeTick.value += 1
}

