    closeSlotActionMenu()
  }
}

onMounted(() => {
  document.addEventListener('click', handleGlobalClick)
  document.addEventListener('keydown', handleKeyDown)
  window.addEventListener('drop', handleWindowDropOrDragEnd)
  window.addEventListener('dragend', handleWindowDropOrDragEnd)
  document.addEventListener('dragleave', handleDocumentDragLeave)
  
  // クリーンアップ用に保存（スロットIDごとに管理）
  if (!document._slotItemDropHandlers) {
    document._slotItemDropHandlers = {}
  }

  bindSlotLeftResizeObserver()
})

watch(
  () => [
    props.beforeAfterCompareLayout,
    props.slot?.id,
    props.compareAfterFileId,
    props.slot?.file_id
  ],
  async () => {
    await nextTick()
    bindSlotLeftResizeObserver()
