onUnmounted(() => {
  document.removeEventListener('mousedown', handleSlotActionMenuOutsideMousedown, true)
  resetDropVisualState()
  document.removeEventListener('click', handleGlobalClick)
  document.removeEventListener('keydown', handleKeyDown)
  window.removeEventListener('drop', handleWindowDropOrDragEnd)
  window.removeEventListener('dragend', handleWindowDropOrDragEnd)
  document.removeEventListener('dragleave', handleDocumentDragLeave)
  if (slotLeftResizeObserver) {
    slotLeftResizeObserver.disconnect()
    slotLeftResizeObserver = null
  }
})

