<template>
  <div v-if="isOpen" class="modal-overlay">
    <div class="modal-content">
      <div class="modal-header">
        <h3>テンプレート登録</h3>
        <button class="close-button" @click="handleClose">&times;</button>
      </div>
      <div class="modal-body">
        <div class="append-section">
          <div class="form-group append-select-group">
            <label for="append-template-select">追加</label>
            <div class="append-control-row">
              <select
                id="append-template-select"
                v-model="selectedTemplateId"
                :disabled="saving"
              >
                <option value="">-- 選択してください --</option>
                <option
                  v-for="tpl in templateLabelOptions"
                  :key="tpl.id"
                  :value="tpl.id"
                >
                  {{ tpl.label }}
                </option>
              </select>
              <button
                type="button"
                class="overwrite-toggle-row"
                :class="{ 'is-on': overwriteHeader }"
                :disabled="saving"
                role="switch"
                :aria-checked="overwriteHeader"
                aria-label="実施事項上書き"
                @click="overwriteHeader = !overwriteHeader"
              >
                <span class="overwrite-toggle-track" aria-hidden="true">
                  <span class="overwrite-toggle-thumb"></span>
                </span>
                <span class="overwrite-label-col">
                  <span class="overwrite-label-line">実施事項</span>
                  <span class="overwrite-label-line">上書き</span>
                </span>
              </button>
            </div>
          </div>
        </div>

        <div class="form-group">
          <label for="template-label">新規名</label>
          <input
            id="template-label"
            type="text"
            v-model="templateLabel"
            placeholder="新規テンプレート名を入力..."
            :disabled="saving || isAppendMode"
            @keydown.enter="handleSave"
            ref="labelInput"
          />
        </div>
        <div v-if="billingItems.length > 0" class="billing-preview">
          <h4>保存される請求項目 ({{ billingItems.length }}件)</h4>
          <div class="billing-items-list">
            <div v-for="(item, index) in billingItems" :key="index" class="billing-item">
              <span class="item-code">{{ item.external_code }}</span>
              <span class="item-description">{{ item.description }}</span>
              <span class="item-quantity">{{ item.quantity || '-' }}</span>
            </div>
          </div>
        </div>
        <div v-if="error" class="error-message">{{ error }}</div>
      </div>
      <div class="modal-footer">
        <button class="cancel-button" @click="handleClose" :disabled="saving">キャンセル</button>
        <button
          class="append-button"
          @click="handleAppend"
          :disabled="!isAppendMode || saving"
          title="選択したテンプレートに請求項目を追加"
        >
          {{ saving ? '処理中...' : '追加' }}
        </button>
        <button
          class="temp-button"
          @click="handleTempSave"
          :disabled="saving || isAppendMode || !!templateLabel.trim()"
          title="一時利用"
        >
          <svg xmlns="http://www.w3.org/2000/svg" width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round">
            <circle cx="12" cy="12" r="10"/>
            <polyline points="12 6 12 12 16 14"/>
          </svg>
          一時
        </button>
        <button
          class="save-button"
          @click="handleSave"
          :disabled="isAppendMode || !templateLabel.trim() || saving"
        >
          {{ saving ? '保存中...' : '保存' }}
        </button>
      </div>
    </div>
  </div>
</template>

<script setup>
import { ref, computed, watch, nextTick } from 'vue'

const props = defineProps({
  isOpen: {
    type: Boolean,
    default: false
  },
  billingItems: {
    type: Array,
    default: () => []
  },
  /** { id, label, sort_order }[] — 利用ボタン押下時に list_labels で取得 */
  templateLabelOptions: {
    type: Array,
    default: () => []
  }
})

const emit = defineEmits(['close', 'save', 'append'])

const templateLabel = ref('')
const selectedTemplateId = ref('')
const overwriteHeader = ref(false)
const saving = ref(false)
const error = ref(null)
const labelInput = ref(null)

const isAppendMode = computed(() => !!selectedTemplateId.value)

watch(() => props.isOpen, (newVal) => {
  if (newVal) {
    templateLabel.value = ''
    selectedTemplateId.value = ''
    overwriteHeader.value = false
    error.value = null
    nextTick(() => {
      labelInput.value?.focus()
    })
  }
})

function handleClose() {
  if (!saving.value) {
    emit('close')
  }
}

async function handleSave() {
  if (!templateLabel.value.trim()) {
    error.value = '新規名を入力してください'
    return
  }
  if (templateLabel.value.trim().toLowerCase() === 'temp') {
    error.value = '「temp」はシステム予約名のため使用できません。一時ボタンをご利用ください'
    return
  }

  saving.value = true
  error.value = null

  try {
    emit('save', templateLabel.value.trim())
  } catch (err) {
    error.value = err.message || 'テンプレートの保存に失敗しました'
    saving.value = false
  }
}

async function handleTempSave() {
  saving.value = true
  error.value = null
  try {
    emit('save', 'temp')
  } catch (err) {
    error.value = err.message || 'テンプレートの保存に失敗しました'
    saving.value = false
  }
}

async function handleAppend() {
  if (!selectedTemplateId.value) return

  saving.value = true
  error.value = null
  try {
    emit('append', {
      templateId: selectedTemplateId.value,
      overwriteHeader: overwriteHeader.value
    })
  } catch (err) {
    error.value = err.message || 'テンプレートへの追加に失敗しました'
    saving.value = false
  }
}

function resetState() {
  saving.value = false
}

function setError(message) {
  error.value = message
  saving.value = false
}

defineExpose({
  resetState,
  setError
})
</script>

<style scoped>
.modal-overlay {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  bottom: 0;
  background: rgba(0, 0, 0, 0.5);
  display: flex;
  align-items: center;
  justify-content: center;
  z-index: 10000;
}

.modal-content {
  background: white;
  border-radius: 0.5rem;
  box-shadow: 0 25px 50px -12px rgba(0, 0, 0, 0.25);
  width: 90%;
  max-width: 500px;
  max-height: 80vh;
  display: flex;
  flex-direction: column;
}

.modal-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 1rem 1.5rem;
  border-bottom: 1px solid #e5e7eb;
}

.modal-header h3 {
  margin: 0;
  font-size: 1.125rem;
  font-weight: 600;
  color: #374151;
}

.close-button {
  background: none;
  border: none;
  font-size: 1.5rem;
  color: #6b7280;
  cursor: pointer;
  padding: 0;
  line-height: 1;
}

.close-button:hover {
  color: #374151;
}

.modal-body {
  padding: 1.5rem;
  overflow-y: auto;
  flex: 1;
}

.append-section {
  margin-bottom: 1.25rem;
  padding-bottom: 1.25rem;
  border-bottom: 1px solid #e5e7eb;
}

.append-select-group {
  margin-bottom: 0;
}

.append-control-row {
  display: flex;
  align-items: center;
  gap: 1rem;
}

.append-control-row select {
  flex: 1;
  min-width: 0;
  padding: 0.75rem;
  border: 1px solid #d1d5db;
  border-radius: 0.375rem;
  font-size: 1rem;
  box-sizing: border-box;
  background: white;
}

.append-control-row select:focus {
  outline: none;
  border-color: #f59e0b;
  box-shadow: 0 0 0 3px rgba(245, 158, 11, 0.1);
}

.append-control-row select:disabled {
  background: #f3f4f6;
  cursor: not-allowed;
}

.form-group {
  margin-bottom: 1rem;
}

.form-group label {
  display: block;
  margin-bottom: 0.5rem;
  font-weight: 500;
  color: #374151;
}

.form-group input:not([type="checkbox"]),
.form-group select {
  width: 100%;
  padding: 0.75rem;
  border: 1px solid #d1d5db;
  border-radius: 0.375rem;
  font-size: 1rem;
  box-sizing: border-box;
  background: white;
}

.form-group input:not([type="checkbox"]):focus,
.form-group select:focus {
  outline: none;
  border-color: #f59e0b;
  box-shadow: 0 0 0 3px rgba(245, 158, 11, 0.1);
}

.form-group input:not([type="checkbox"]):disabled,
.form-group select:disabled {
  background: #f3f4f6;
  cursor: not-allowed;
}

.overwrite-toggle-row {
  display: flex;
  align-items: center;
  gap: 0.375rem;
  flex-shrink: 0;
  border: none;
  background: transparent;
  padding: 0;
  margin: 0;
  cursor: pointer;
  text-align: left;
  font: inherit;
}

.overwrite-toggle-row:disabled {
  cursor: not-allowed;
  opacity: 0.5;
}

.overwrite-toggle-track {
  display: block;
  flex-shrink: 0;
  width: 2.25rem;
  height: 1.25rem;
  border-radius: 9999px;
  background: #d1d5db;
  position: relative;
  transition: background-color 0.2s;
}

.overwrite-toggle-row.is-on .overwrite-toggle-track {
  background: #059669;
}

.overwrite-toggle-thumb {
  position: absolute;
  top: 0.125rem;
  left: 0.125rem;
  width: 1rem;
  height: 1rem;
  border-radius: 50%;
  background: white;
  box-shadow: 0 1px 2px rgba(0, 0, 0, 0.15);
  transition: transform 0.2s;
}

.overwrite-toggle-row.is-on .overwrite-toggle-thumb {
  transform: translateX(1rem);
}

.overwrite-label-col {
  display: flex;
  flex-direction: column;
  line-height: 1.2;
  gap: 0.125rem;
  font-size: 0.875rem;
  color: #374151;
  user-select: none;
}

.overwrite-label-line {
  display: block;
  white-space: nowrap;
}

.billing-preview {
  margin-top: 1rem;
  padding: 1rem;
  background: #f9fafb;
  border-radius: 0.375rem;
}

.billing-preview h4 {
  margin: 0 0 0.75rem 0;
  font-size: 0.875rem;
  font-weight: 600;
  color: #6b7280;
}

.billing-items-list {
  max-height: 200px;
  overflow-y: auto;
}

.billing-item {
  display: flex;
  gap: 0.5rem;
  padding: 0.5rem 0;
  border-bottom: 1px solid #e5e7eb;
  font-size: 0.875rem;
}

.billing-item:last-child {
  border-bottom: none;
}

.item-code {
  font-weight: 500;
  color: #6b7280;
  min-width: 80px;
}

.item-description {
  flex: 1;
  color: #374151;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.item-quantity {
  color: #6b7280;
  min-width: 40px;
  text-align: right;
}

.error-message {
  margin-top: 1rem;
  padding: 0.75rem;
  background: #fee2e2;
  color: #dc2626;
  border-radius: 0.375rem;
  font-size: 0.875rem;
}

.modal-footer {
  display: flex;
  justify-content: flex-end;
  gap: 0.75rem;
  padding: 1rem 1.5rem;
  border-top: 1px solid #e5e7eb;
  flex-wrap: wrap;
}

.cancel-button,
.append-button,
.temp-button,
.save-button {
  padding: 0.5rem 1rem;
  border-radius: 0.375rem;
  font-size: 0.875rem;
  font-weight: 500;
  cursor: pointer;
  transition: all 0.2s;
  display: inline-flex;
  align-items: center;
  gap: 0.375rem;
}

.cancel-button {
  background: white;
  border: 1px solid #d1d5db;
  color: #374151;
}

.cancel-button:hover:not(:disabled) {
  background: #f3f4f6;
}

.append-button {
  background: #059669;
  border: 1px solid #059669;
  color: white;
}

.append-button:hover:not(:disabled) {
  background: #047857;
  border-color: #047857;
}

.temp-button {
  padding: 0.5rem 1rem;
  background: #dbeafe;
  border: 1px solid #93c5fd;
  color: #2563eb;
}

.temp-button:hover:not(:disabled) {
  background: #bfdbfe;
  border-color: #60a5fa;
}

.save-button {
  background: #f59e0b;
  border: 1px solid #f59e0b;
  color: white;
}

.save-button:hover:not(:disabled) {
  background: #d97706;
  border-color: #d97706;
}

.cancel-button:disabled,
.append-button:disabled,
.temp-button:disabled,
.save-button:disabled {
  opacity: 0.5;
  cursor: not-allowed;
}
</style>
