/**
 * プライスリストの並び・既定選択用: fiscal_year 降順、同年度内は revision_no 降順
 * @param {Record<string, unknown>} a
 * @param {Record<string, unknown>} b
 * @returns {number}
 */
export function comparePriceListsByFiscalThenRevision(a, b) {
  const fyA = Number(a?.fiscal_year)
  const fyB = Number(b?.fiscal_year)
  const nfyA = Number.isFinite(fyA) ? fyA : 0
  const nfyB = Number.isFinite(fyB) ? fyB : 0
  if (nfyB !== nfyA) return nfyB - nfyA
  const revA = Number(a?.revision_no)
  const revB = Number(b?.revision_no)
  const nrevA = Number.isFinite(revA) ? revA : 0
  const nrevB = Number.isFinite(revB) ? revB : 0
  return nrevB - nrevA
}
